// ==================== SISTEMA DE SEGUIMIENTO DE JUGADORES ====================
// Estructura: playerOrderByTeam[team] = [playerId1, playerId2, ...]  (0=spec, 1=red, 2=blue)
let playerOrderByTeam = {
    0: [], // Espectadores
    1: [], // Equipo Red
    2: []  // Equipo Blue
};

/**
 * Agrega un jugador al final de la lista de su equipo
 * @param {number} playerId - ID del jugador
 * @param {number} team - Número del equipo (0, 1, 2)
 */
function addPlayerToTeamOrder(playerId, team) {
    if (team < 0 || team > 2) return;
    if (!playerOrderByTeam[team].includes(playerId)) {
        playerOrderByTeam[team].push(playerId);
    }
}

/**
 * Remueve un jugador de su equipo actual
 * @param {number} playerId - ID del jugador
 */
function removePlayerFromTeamOrder(playerId) {
    for (let team = 0; team <= 2; team++) {
        const index = playerOrderByTeam[team].indexOf(playerId);
        if (index !== -1) {
            playerOrderByTeam[team].splice(index, 1);
            break;
        }
    }
}

/**
 * Mueve un jugador de un equipo a otro
 * @param {number} playerId - ID del jugador
 * @param {number} newTeam - Número del equipo nuevo (0, 1, 2)
 */
function movePlayerToTeamOrder(playerId, newTeam) {
    removePlayerFromTeamOrder(playerId);
    addPlayerToTeamOrder(playerId, newTeam);
}

/**
 * Obtiene el primer jugador del equipo
 * @param {number} team - Número del equipo (0, 1, 2)
 * @returns {object|null} Objeto del jugador o null si no hay jugadores
 */
function getFirstPlayer(team) {
    if (team < 0 || team > 2) return null;

    const playerList = room.getPlayerList();
    const teamPlayers = playerOrderByTeam[team];

    // Validar que los jugadores en la lista sigan siendo válidos
    for (let playerId of teamPlayers) {
        const player = playerList.find(p => p.id === playerId);
        if (player && player.team === team) {
            return player;
        }
    }

    return null;
}

/**
 * Sincroniza la estructura interna con el estado real del juego
 * Útil para corregir desincronizaciones
 */
function syncPlayerTeamOrder() {
    playerOrderByTeam = { 0: [], 1: [], 2: [] };
    const playerList = room.getPlayerList();

    for (let player of playerList) {
        if (player.id !== 0) { // Ignorar el host
            addPlayerToTeamOrder(player.id, player.team);
        }
    }
}

/**
 * Obtiene un resumen del orden de jugadores por equipo
 * @returns {object} Objeto con nombres de jugadores por equipo
 */
function getTeamOrderSummary() {
    const playerList = room.getPlayerList();
    const summary = {};
    const teamNames = { 0: 'Espectadores', 1: 'Red', 2: 'Blue' };

    for (let team = 0; team <= 2; team++) {
        summary[teamNames[team]] = playerOrderByTeam[team]
            .map(id => {
                const player = playerList.find(p => p.id === id);
                return player ? player.name : `[ID: ${id}]`;
            })
            .filter(name => name !== null);
    }

    return summary;
}
// ==================== FIN SISTEMA DE SEGUIMIENTO ====================

