// Función para activar verificación de posiciones
function startPositionCheck() {
    if (isPositionCheckActive) return; // Evita duplicados

    isPositionCheckActive = true;
    positionCheckInterval = setInterval(() => {
        if (matchON && requirePosition) { // Verifica también si el partido está activo
            checkPlayerPositions();
        }
    }, 2000); // Verificar cada 2 segundos
}

// Función para detener verificación
function stopPositionCheck() {
    if (positionCheckInterval !== null) {
        clearInterval(positionCheckInterval);
        positionCheckInterval = null;
        isPositionCheckActive = false;
    }
}

// Usar en tu lógica
if (requirePosition) {
    startPositionCheck();
} else {
    stopPositionCheck();
}

function isValidHexColor(hexString) {
    // Acepta: 0xFF0000, 0xff0000, FF0000, ff0000
    const match = hexString.match(/^0?x?[0-9a-fA-F]{6}$/);
    if (!match) return false;

    // Convertir a 0xHEXHEX
    let hex = hexString.replace(/^0x/i, '0x').toUpperCase();
    if (!hex.startsWith('0x')) hex = '0x' + hex;

    return { isValid: true, hex: parseInt(hex) };
}

function getVipChatColor(player) {
    // 1. Chequear si tiene color temporal (comando !c)
    if (tempVipChatColors.has(player.id)) {
        const data = tempVipChatColors.get(player.id);
        if (Date.now() < data.expiryTime) {
            return data.color;
        } else {
            tempVipChatColors.delete(player.id);
        }
    }

    // 2. Chequear si tiene color predefinido usando playerAuthMap
    const playerAuth = playerAuthMap.get(player.id); // ← USAR playerAuthMap EN LUGAR DE player.auth
    if (playerAuth && vipChatColors.has(playerAuth)) {
        return vipChatColors.get(playerAuth);
    }

    // 3. Color por defecto
    return colors.vip;
}

