function checkPlayerCount() {
    if (roomlockmode === 1) {
        // Si está en modo cerrado, no hacer nada
        return;
    }
    if (roomlockmode === 0) {
        if (roomPublicMode === 1) {
            // Sala forzada pública, no modificar contraseña
            room.setPassword(null);
            return;
        }
        const playerCount = room.getPlayerList().length;
        if (playerCount >= MAX_PLAYERS_BEFORE_PASSWORD) {
            if (!noVerifiedMode) {
                verifiedOnlyMode = true;
                room.setPassword(ROOM_PASSWORD);
            } else if (noVerifiedMode) {
                room.setPassword(null);
            }
        } else {
            room.setPassword(null);
            if (todosjuegan || dtsMode) {
                if (!noVerifiedMode) {
                    verifiedOnlyMode = false;
                }
            }
        }
    }
}
