function simplifyPlayerName(name) {
    if (!name) return "Unknown";

    let simplified = name
        .replace(/[\u{1F300}-\u{1F9FF}]/gu, '') // Emojis
        .replace(/[\u{2600}-\u{27BF}]/gu, '')   // Símbolos especiales
        .replace(/[^\w\s\-áéíóúñÁÉÍÓÚÑ]/g, '')  // Remover caracteres especiales
        .trim()
        .replace(/\s+/g, ' '); // Normalizar espacios

    return simplified.length > 0 ? simplified : name.substring(0, 20);
}

function initMvpStats(player) {
    mvpStats[player.id] = {
        name: simplifyPlayerName(player?.name) || "Unknown",  // ✅ AGREGADO y SIMPLIFICADO
        goals: 0,
        assists: 0,
        touches: 0,
        shots: 0,
        saves: 0,
        ballRecoveries: 0,
        distanceTraveled: 0,
        passesCompleted: 0,
        passesFailed: 0,
        KeyPasses: 0,
        longPasses: 0, // <--- ADD THIS LINE
        dribbling: 0,
        ownGoals: 0,
        goalsConceded: 0,
        mvpScore: 0, // Inicializar mvpScore
        lastKeyPassTick: null,
        lastPosition: { x: 0, y: 0 },
        matchesPlayed: 0,
        matchesWon: 0,
        matchesLost: 0,
        gamesPlayed: 0,
        gamesWon: 0,
        gamesLost: 0,
        gamesDrawn: 0,
        mvps: 0,
    };
}

function loadPlayerStats(auth, player = null) {
    const stats = localStorage.getItem(auth);
    if (stats) {
        return JSON.parse(stats);
    }
    const defaultStats = {
        name: player?.name || "Unknown",  // ✅ AGREGADO
        goals: 0,
        assists: 0,
        matchesPlayed: 0,
        matchesWon: 0,
        matchesLost: 0,
        gamesPlayed: 0,
        gamesWon: 0,
        gamesLost: 0,
        gamesDrawn: 0,
        mvps: 0,
        saves: 0,
        passes: 0,
        shots: 0,
        interceptions: 0,
        tackles: 0,
    };
    if (player) {
        initMvpStats(player);
        return mvpStats[player.id];
    }
    console.warn(`No se encontraron estadísticas para el auth: ${auth}. Se usarán valores predeterminados.`);
    return defaultStats;
}

function savePlayerStats(auth, stats, globalStats) {
    if (globalStats) {
        stats = globalStats;
    }
    localStorage.setItem(auth, JSON.stringify(stats));
}

function updatePlayerStats(auth, statKey, value, player = null) {
    const stats = loadPlayerStats(auth, player);
    stats[statKey] = (stats[statKey] || 0) + value;
    savePlayerStats(auth, stats);
}
// Helpers para localStorage
function getRankings() {
    let data = localStorage.getItem("haxball_rankings");
    return data ? JSON.parse(data) : {};
}

function saveRankings(rankings) {
    localStorage.setItem("haxball_rankings", JSON.stringify(rankings));
}

function getWeightedRandomPosition() {
    // Crear array expandido según pesos
    let weightedArray = [];
    for (const [posicion, peso] of Object.entries(POSICION_WEIGHTS)) {
        for (let i = 0; i < peso; i++) {
            weightedArray.push(posicion);
        }
    }
    // Retornar elemento aleatorio
    return weightedArray[Math.floor(Math.random() * weightedArray.length)];
}

