        console.log(`✅ Reporte sobre ${targetPlayer.name} Los administradores han sido notificados.`);
        room.sendAnnouncement(`🚨 ¡Se ha reportado a ${targetPlayer.name}! \n Motivo: ${reason}`, null, colors.botGold, "bold", 2);

        return false;
