function assignReferee(player) {
    referees.add(player.id);
    room.setPlayerAdmin(player.id, true);
}

function assignRole(player, role, index) {
    let players = room.getPlayerList();
    if (index < 1 || index > players.length) {
        room.sendAnnouncement("Índice de jugador inválido.", player.id, colors.bot, "bold", 2);
        return;
    }
    let targetPlayer = players[index - 1];

    if (!targetPlayer) {
        room.sendAnnouncement("Jugador no encontrado.", player.id, colors.bot, "bold", 2);
        return;
    }

    if (role === "admin") {
        admins.add(targetPlayer.id);
        room.setPlayerAdmin(targetPlayer.id, true);
        room.sendAnnouncement(`#${targetPlayer.name} 𝐡𝐚 𝐬𝐢𝐝𝐨 𝐩𝐫𝐨𝐦𝐨𝐯𝐢𝐝𝐨 𝐚 𝐚𝐝𝐦𝐢𝐧𝐢𝐬𝐭𝐫𝐚𝐝𝐨𝐫.`, null, colors.admin, "bold", 2);
    } else if (role === "DTred") {
        dts.red = targetPlayer.id;
        room.sendAnnouncement(`#${targetPlayer.name} 𝘦𝘴 𝘢𝘩𝘰𝘳𝘢 𝘦𝘭 𝘋𝘛 𝘥𝘦𝘭 𝘦𝘲𝘶𝘪𝘱𝘰 𝘙𝘰𝘫𝘰 👔📋✍️.`, null, colors.bot, "bold", 2);
    } else if (role === "DTblue") {
        dts.blue = targetPlayer.id;
        room.sendAnnouncement(`#${targetPlayer.name} 𝘦𝘴 𝘢𝘩𝘰𝘳𝘢 𝘦𝘭 𝘋𝘛 𝘥𝘦𝘭 𝘦𝘲𝘶𝘪𝘱𝘰 𝘈𝘻𝘶𝘭 👔📋✍️.`, null, colors.bot, "bold", 2);
    }
}

function assignDT(player) {
    if (player.id === dts.red || player.id === dts.blue) {
        room.sendAnnouncement(`${player.name} ya es DT de un equipo. No puede ser DT de ambos equipos.`, player.id, colors.bot, "bold", 2);
        return;
    }

    if (!dts.red) {
        dts.red = player.id;
        room.sendAnnouncement(`${player.name} 𝙃𝘼 𝙎𝙄𝘿𝙊 𝘼𝙎𝙄𝙂𝙉𝘼𝘿𝙊 𝘾𝙊𝙈𝙊 𝘿𝙏 𝘿𝙀𝙇 𝙀𝙌𝙐𝙄𝙋𝙊 𝙍𝙊𝙅𝙊! 🔴.`, null, colors.dtRed, "bold", 2);
    } else if (!dts.blue) {
        dts.blue = player.id;
        room.sendAnnouncement(`${player.name} 𝙃𝘼 𝙎𝙄𝘿𝙊 𝘼𝙎𝙄𝙂𝙉𝘼𝘿𝙊 𝘾𝙊𝙈𝙊 𝘿𝙏 𝘿𝙀𝙇 𝙀𝙌𝙐𝙄𝙋𝙊 𝘼𝙕𝙐𝙇! 🔵`, null, colors.dtBlue, "bold", 2);
    } else {
        room.sendAnnouncement("Ambos roles de DT ya están ocupados.", player.id, colors.bot, "bold", 2);
    }
    updatePlayerRoles();
}

function asignarCapitanAleatorio(equipo) {
    // equipo: "red" o "blue"
    const teamNum = equipo === "red" ? 1 : 2;
    // Filtra jugadores del equipo, que no sean DT ni referee
    const jugadoresElegibles = room.getPlayerList().filter(p =>
        p.team === teamNum &&
        p.id !== dts.red &&
        p.id !== dts.blue &&
        !referees.has(p.id)
    );
    if (jugadoresElegibles.length === 0) {
        room.sendAnnouncement(`No hay jugadores elegibles para capitán en el equipo ${equipo}.`, null, colors.bot, "bold", 2);
        return;
    }
    // Elige uno al azar
    const elegido = jugadoresElegibles[Math.floor(Math.random() * jugadoresElegibles.length)];
    captains[equipo] = elegido.id;
    updatePlayerRoles(); // Si tienes una función para actualizar avatares/roles
    room.sendAnnouncement(`▌ 𝗡𝗨𝗘𝗩𝗢 𝗖𝗔𝗣𝗜𝗧𝗔𝗡 ${equipo === "red" ? "𝗥𝗘𝗗 🔴" : "𝗕𝗟𝗨𝗘 🔵"}: ${elegido.name.toUpperCase()} ▐`, null, equipo === "red" ? colors.dtRed : colors.dtBlue, "bold", 2);
}

function assignReferee(player) {
    referees.add(player.id);
    room.setPlayerAdmin(player.id, true); // Opcional: dar permisos de administrador
    room.sendAnnouncement(`${player.name} 𝗘𝗦 𝗡𝗨𝗘𝗩𝗢 𝗝𝗨𝗚𝗔𝗗𝗢𝗥 𝗗𝗘𝗟 𝗥𝗘𝗔𝗟 𝗠𝗔𝗗𝗥𝗜𝗗 , 𝗗𝗜𝗚𝗢 𝗔𝗥𝗕𝗜𝗧𝗥𝗢.`, null, colors.referee, "bold", 2);
}

function asignarRolCreador(authList) {
    let jugadores = room.getPlayerList();
    for (let i = 0; i < jugadores.length; i++) {
        if (authList.includes(jugadores[i].auth)) {
            // Asignar el rol de creador y administrador
            creator = jugadores[i].id;
            admins.add(jugadores[i].id);
            room.setPlayerAdmin(jugadores[i].id, true); // Dar permisos de administrador
            room.sendAnnouncement(`¡${jugadores[i].name} ahora es el creador y administrador!`, null, 0x00FF00, "bold", 2);
            return;
        }
    }
    room.sendAnnouncement("No se encontró al jugador con el auth proporcionado.", null, 0xFF0000, "bold", 2);
}

function handleYODTRequest(player) {
    // Si ya hay una petición pendiente, no permitir otra
    if (pendingYODTRequest) {
        room.sendAnnouncement("Ya hay una petición de DT pendiente. Espera a que el creator responda.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Guardar la petición pendiente
    pendingYODTRequest = { playerId: player.id, timestamp: Date.now() };

    // Anunciar globalmente
    room.sendAnnouncement(`𝗘𝗟 𝗣𝗘𝗡𝗗𝗘𝗝𝗢 𝗗𝗘 ${player.name} 𝗛𝗔 𝗦𝗢𝗟𝗜𝗖𝗜𝗧𝗔𝗗𝗢 𝗦𝗘𝗥 𝗗𝗧`, null, colors.botGold, "bold", 2);

    // Mensaje privado al creator
    if (creator) {
        room.sendAnnouncement(`¿Aceptas a ${player.name} como DT? Escribe "si" o "no".`, creator, colors.botGold, "bold", 2);
    }

    return false;
}

function charlaTecnica(on) {
    if (on) {
        if (charlaTecnicaActiva) return; // Ya está activa

        charlaTecnicaActiva = true;
        charlaTecnicaStartTime = Date.now();

        // Silencio global 15 segundos
        room.sendAnnouncement(
            ` \n 🔇 ¡𝐂𝐇𝐀𝐑𝐋𝐀 𝐓𝐄́𝐂𝐍𝐈𝐂𝐀 𝐈𝐍𝐈𝐂𝐈𝐀𝐃𝐀! 🔇\n `,
            null, colors.botGold, "bold", 2
        );

        // Nombres de los DTs
        let dtRedName = dts.red ? (room.getPlayer(dts.red)?.name || "N/A") : "N/A";
        let dtBlueName = dts.blue ? (room.getPlayer(dts.blue)?.name || "N/A") : "N/A";
        room.sendAnnouncement(
            `🗣️ DTs: 🔴 ${dtRedName} | 🔵 ${dtBlueName}\nEn breve, cada equipo podrá hablar solo entre sí.`,
            null, colors.botGold, "bold", 2
        );

        // Después de 15s, activa modo charla por equipos (45s restantes)
        charlaTecnicaTimeout = setTimeout(() => {

            room.sendAnnouncement(
                `🗣️ ¡𝐂𝐇𝐀𝐑𝐋𝐀 𝐓𝐄́𝐂𝐍𝐈𝐂𝐀 𝐀𝐂𝐓𝐈𝐕𝐀! 🗣️\nSolo puedes hablar y leer mensajes de tu equipo durante 60 segundos.\nLos DTs pueden dar indicaciones.`,
                null, colors.botGold, "bold", 2
            );
            // Programa el fin de la charla técnica a los 60s desde aquí
            charlaTecnicaFinTimeout = setTimeout(() => {
                charlaTecnicaActiva = false;

                room.sendAnnouncement(
                    `✅ ¡𝐂𝐇𝐀𝐑𝐋𝐀 𝐓𝐄́𝐂𝐍𝐈𝐂𝐀 𝐅𝐈𝐍𝐀𝐋𝐈𝐙𝐀𝐃𝐀! El chat vuelve a la normalidad.`,
                    null, colors.botGold, "bold", 2
                );
            }, 60000);
        }, 15000);

    } else {
        // Desactivar charla técnica antes de tiempo
        if (!charlaTecnicaActiva) return;
        charlaTecnicaActiva = false;
        charlaTecnicaSilencio = false;
        if (charlaTecnicaTimeout) clearTimeout(charlaTecnicaTimeout);
        if (charlaTecnicaFinTimeout) clearTimeout(charlaTecnicaFinTimeout);
        room.sendAnnouncement(
            `⛔ 𝐂𝐇𝐀𝐑𝐋𝐀 𝐓𝐄́𝐂𝐍𝐈𝐂𝐀 𝐂𝐀𝐍𝐂𝐄𝐋𝐀𝐃𝐀. El chat vuelve a la normalidad.`,
            null, colors.botGold, "bold", 2
        );
    }
}

function normalizarFrase(frase) {
    return frase
        .toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // quita tildes
        .replace(/[¿?¡!.,]/g, "") // quita signos de puntuación
        .replace(/\s+/g, " ") // espacios múltiples a uno solo
        .trim();
}

function setTeamUniforms() {
    const randomIndex = Math.floor(Math.random() * uniformOptions.length);
    const selectedUniform = uniformOptions[randomIndex];

    // Configuración para el equipo rojo
    const redTeam = 1; // Identificador del equipo rojo
    const redConfig = selectedUniform.red;

    // Configuración para el equipo azul
    const blueTeam = 2; // Identificador del equipo azul
    const blueConfig = selectedUniform.blue;

    // Guardar en memoria
    currentUniform.red = { ...redConfig };
    currentUniform.blue = { ...blueConfig };


    // Aplicar uniformes
    room.setTeamColors(redTeam, redConfig.angle, redConfig.textColor, redConfig.colors); // Uniforme para el equipo rojo
    room.setTeamColors(blueTeam, blueConfig.angle, blueConfig.textColor, blueConfig.colors); // Uniforme para el equipo azul
}
function adjustScore(action, numGoles, equipo, tipo) {
    const team = equipo === "rojo" ? 1 : 2;

    if (tipo === "ida") {
        if (action === "+") {
            if (team === 1) {
                matchStats.ida.redScore += numGoles;
            } else {
                matchStats.ida.blueScore += numGoles;
            }
        } else {
            if (team === 1) {
                matchStats.ida.redScore -= numGoles;
            } else {
                matchStats.ida.blueScore -= numGoles;
            }
        }
    } else {
        if (action === "+") {
            if (team === 1) {
                matchStats.vuelta.redScore += numGoles;
            } else {
                matchStats.vuelta.blueScore += numGoles;
            }
        } else {
            if (team === 1) {
                matchStats.vuelta.redScore -= numGoles;
            } else {
                matchStats.vuelta.blueScore -= numGoles;
            }
        }
    }

    const globalRedScore = matchStats.ida.redScore + matchStats.vuelta.redScore;
    const globalBlueScore = matchStats.ida.blueScore + matchStats.vuelta.blueScore;

    room.sendAnnouncement(`𝙈𝘼𝙍𝘾𝘼𝘿𝙊𝙍 𝙈𝙊𝘿𝙄𝙁𝙄𝘾𝘼𝘿𝙊 \n𝙄𝘿𝘼: 🔴 ⦅ ${matchStats.ida.redScore} - ${matchStats.ida.blueScore} ⦆ 🔵 \n𝙑𝙐𝙀𝙇𝙏𝘼: 🔴 ⦅ ${matchStats.vuelta.redScore} - ${matchStats.vuelta.blueScore} ⦆ 🔵 \n𝙂𝙇𝙊𝘽𝘼𝙇: 🔴 ⦅ ${globalRedScore} - ${globalBlueScore} ⦆ 🔵 `, null, colors.botGold, "bold", 2);
}

