function swapTeamUniforms() {
    if (!currentUniform.red || !currentUniform.blue) {
        room.sendAnnouncement("❌ No hay uniformes cargados aún.", null, 0xFF0000, "bold", 2);
        return;
    }

    const redTeam = 1;
    const blueTeam = 2;

    // Intercambiar estructuras en memoria
    const temp = currentUniform.red;
    currentUniform.red = currentUniform.blue;
    currentUniform.blue = temp;

    // Aplicar intercambio
    room.setTeamColors(redTeam, currentUniform.red.angle, currentUniform.red.textColor, currentUniform.red.colors);
    room.setTeamColors(blueTeam, currentUniform.blue.angle, currentUniform.blue.textColor, currentUniform.blue.colors);

    room.sendAnnouncement("🔄 Uniformes intercambiados", null, 0xFFFFFF, "bold", 2);
}


