function mutePlayerById(playerId, duration) {
    const player = room.getPlayer(playerId);
    if (!player) {
        room.sendAnnouncement("Jugador no encontrado.", null, colors.bot, "bold", 2);
        return;
    }

    // Guardar en el mapa persistente usando auth
    const auth = playerAuthMap.get(playerId); // 🔑 OBTENER AUTH DEL MAPA
    if (!auth) {
        room.sendAnnouncement("Error: No se pudo obtener el auth del jugador.", null, colors.bot, "bold", 2);
        return;
    }

    // Guardar: auth => { expiryTime, duration }
    persistentMutedPlayers.set(auth, {
        muteTime: Date.now(),
        duration: duration,
        expiryTime: Date.now() + duration * 1000
    });

    mutedPlayers.set(player.id, Date.now() + duration * 1000);
    room.setPlayerAvatar(player.id, "🔇");
    room.sendAnnouncement(
        `🔇 ${player.name} 𝙎𝙄𝙇𝙀𝙉𝘾𝙄𝘼𝘿𝙊 𝙋𝙊𝙍 ${duration} 𝙎𝙀𝙂𝙐𝙉𝘿𝙊𝙎.`,
        null,
        colors.botGold,
        "bold",
        2
    );

    // Timeout para remover automáticamente
    setTimeout(() => {
        if (mutedPlayers.has(player.id)) {
            mutedPlayers.delete(player.id);
            persistentMutedPlayers.delete(auth);
            room.setPlayerAvatar(player.id, null);
            room.sendAnnouncement(
                `${player.name} ya no está silenciado.`,
                player.id,
                colors.bot,
                "bold",
                2
            );
        }
    }, duration * 1000);
}

function unmutePlayerById(playerId) {
    const player = room.getPlayer(playerId);
    if (!player) {
        room.sendAnnouncement("Jugador no encontrado.", null, colors.bot, "bold", 2);
        return;
    }

    const auth = playerAuthMap.get(playerId); // 🔑 OBTENER AUTH
    if (!auth) {
        room.sendAnnouncement("Error: No se pudo obtener el auth del jugador.", null, colors.bot, "bold", 2);
        return;
    }

    if (mutedPlayers.has(player.id)) {
        mutedPlayers.delete(player.id);
        persistentMutedPlayers.delete(auth);
        room.setPlayerAvatar(player.id, null);
        room.sendAnnouncement(
            `${player.name} ya no está silenciado.`,
            player.id,
            colors.bot,
            "bold",
            2
        );
    } else {
        room.sendAnnouncement(
            `${player.name} no estaba silenciado.`,
            null,
            colors.bot,
            "bold",
            2
        );
    }
}

// Guardar el conjunto en localStorage
function saveMutedPlayers() {
    localStorage.setItem("mutedPlayers", JSON.stringify(Array.from(persistentMutedPlayers)));
}

// Cargar el conjunto desde localStorage
function loadMutedPlayers() {
    const savedMutedPlayers = localStorage.getItem("mutedPlayers");
    if (savedMutedPlayers) {
        persistentMutedPlayers = new Map(JSON.parse(savedMutedPlayers));
    }
}

// Llamar a la función de carga al iniciar la sala
