function enableSlowMode(seconds) {
    slowModeEnabled = true;
    slowModeDuration = seconds;
    lastMessageTime = new Map(); // Cambiar a Map en lugar de {}
    setTimeout(() => {
        slowModeEnabled = false;
        room.sendAnnouncement("Modo lento desactivado.", null, colors.bot, "bold", 2);
    }, seconds * 1000); // Cambié 3000 a 1000 para que coincida con segundos reales
}

function handleMuteCommand(player, duration) {
    const isAdmin = admins.has(player.id) || player.id === creator || hosters.has(player.id) || referees.has(player.id) || vips.has(player.id) || captains.red === player.id || captains.blue === player.id;

    if (!isAdmin) {
        room.sendAnnouncement("No tienes permiso para usar este comando.", player.id, colors.bot, "bold", 2);
        return false;
    }

    room.getPlayerList().forEach(p => {
        const isExempt = admins.has(p.id) || p.id === creator || hosters.has(p.id) || referees.has(p.id) || vips.has(p.id) || captains.red === p.id || captains.blue === p.id || dts.red === p.id || dts.blue === p.id;

        if (!isExempt) {
            mutedPlayers.set(p.id, Date.now() + duration * 1000);
            room.setPlayerAvatar(p.id, "🔇");
        }
    });

    room.sendAnnouncement(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    𝖢𝖧𝖠𝖳 𝖬𝖴𝖳𝖤𝖠𝖣𝖮 ${duration} 𝖲𝖤𝖦𝖴𝖭𝖣𝖮𝖲 🔇
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`, null, colors.botGold, "bold", 2);

    setTimeout(() => {
        unmutePlayers();
    }, duration * 1000);

    return false;
}

function enableSlowModeForPlayer(playerId, duration) {
    slowModePlayers.set(playerId, duration);
    setTimeout(() => {
        slowModePlayers.delete(playerId);
        room.sendAnnouncement(`Modo lento desactivado para el jugador con ID ${playerId}.`, null, colors.bot, "bold", 2);
    }, duration * 2000);
}

function handleMessage(player, message) {
    const currentTime = Date.now();
    if (slowModeEnabled || slowModePlayers.has(player.id)) {
        const lastTime = lastMessageTime.get(player.id) || 0; // Usar .get() porque ahora es un Map
        if (currentTime - lastTime < slowModeDuration * 1000) {
            room.sendAnnouncement("Estás en modo lento. Espera antes de enviar otro mensaje.", player.id, colors.bot, "bold", 2);
            return false;
        }
        lastMessageTime.set(player.id, currentTime); // Usar .set() porque ahora es un Map
    }
    // ...existing code...
}

function isAdmin(player) {
    return admins.has(player.id) || player.id === creator || hosters.has(player.id);
}

function isDT(player) {
    return player.id === dts.red || player.id === dts.blue;
}

function isCreator(player) {
    return player.id === creator || hosters.has(player.id);
}

function saveUniformCommand(player, message) {
    const team = room.getPlayer(player.id).team;
    if (team === 1) {
        uniformCommands.red = message;
    } else if (team === 2) {
        uniformCommands.blue = message;
    }
}

