function mostrarPublicidad() {
    const publicidadAleatoria = publicidad[Math.floor(Math.random() * publicidad.length)];
    room.sendAnnouncement(`══════════════════════════════════════════════════
${publicidadAleatoria}
══════════════════════════════════════════════════`, null, colors.botGold, "bold", 0);
}

