setInterval(() => {
    mostrarPublicidad();

    if (AnuncioKL === true) {
        setTimeout(() => {
            AnuncioKnightsLeague();
        }, 3000);
    }


    if (AnuncioMC === true) {
        setTimeout(() => {
            AnuncioMelchorsChampions();
        }, 5000);
    }

    if (narrador === 1) {
        setTimeout(() => {
            AnuncioNarracion();
        }, 10000);
    }

    if (dtspeakbot === 1) {
        setTimeout(() => {
            AnunciosDTspeak();
        }, 20000);
    }

}, 60000);

// Mostrar una regla aleatoria cada 10 minutos (600000 milisegundos)
setInterval(mostrarReglaAleatoria, 300000);

function handleAfkCommand(player) {
    if (afkPlayers.has(player.id)) {
        room.setPlayerAvatar(player.id, null);
        afkPlayers.delete(player.id);
        if (todosjuegan) { // Si NO está en modo dts
            startAfkTimer(player);
            stopAfkTimer(player);
            return false;
        }
        room.sendAnnouncement(`${player.name} ya no está AFK`, null, colors.bot, "bold", 2);
    } else {
        const afkAvatar = "😴";
        const originalAvatar = player.avatar; // Asegurarse de obtener el avatar actual
        afkPlayers.set(player.id, originalAvatar);
        room.setPlayerAvatar(player.id, afkAvatar);

        // ────────────────────────────────────────────
        // AF4v4mode: Manejar si el picker se vuelve AFK
        // ────────────────────────────────────────────
        if (AF4v4mode && af4PickPhase && af4PickerActual?.id === player.id) {
            handlePickerAfk(player);
            return false;
        }

        if (todosjuegan || AF4v4mode) { // Si NO está en modo dts
            room.setPlayerTeam(player.id, 0); // 0 = espectadores
            room.sendAnnouncement(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
⚠️ ${player.name} 𝗘𝗦𝗧𝗔 𝗔𝗙𝗞, 𝗛𝗔 𝗦𝗜𝗗𝗢 𝗠𝗢𝗩𝗜𝗗𝗢 𝗔 𝗘𝗦𝗣𝗘𝗖𝗧𝗔𝗗𝗢𝗥𝗘𝗦.
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`, player.id, colors.bot, "bold", 2);
            startAfkTimer(player);
            stopAfkTimer(player);

            // ─── PARTE 1: AF4v4mode - Lógica de early/late leave ───
            if (AF4v4mode && matchON && !af4PickPhase) {
                if (isEarlyLeave()) {
                    console.log("[AF4v4] !afk early — deteniendo partido");
                    af4EarlyStop = true;
                    af4StoppingGame = true;
                    room.stopGame();
                } else {
                    console.log("[AF4v4] !afk tardío — pausando para repick");
                    if (!af4RepickInProgress) {
                        af4IsPaused = true;
                        af4RepickInProgress = true;
                        room.pauseGame();

                        setTimeout(() => {
                            const redCount = af4CountTeam(1);
                            const blueCount = af4CountTeam(2);
                            af4PickPhase = true;
                            af4EquipoPick = (redCount < 4) ? 1 : 2;
                            af4StartPickTurn();
                        }, 200);
                    }
                }
            }

            return false;
        }
        room.sendAnnouncement(`${player.name} está ahora AFK.`, null, colors.bot, "bold", 2);
    }
}

function Cambio(player, message) {
    // Verificar si el jugador es DT o Creador
    if (player.id !== creator && player.id !== dts.red && player.id !== dts.blue) {
        room.sendAnnouncement("No tienes permiso para usar este comando.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const args = message.split(" ");
    if (args.length !== 4 || args[2].toLowerCase() !== "x") {
        room.sendAnnouncement("Uso incorrecto. Usa !cambio id x id. usa !list o !jugadores red/blue para ver las id", player.id, colors.bot, "normal", 2);
        return false;
    }

    const idSale = parseInt(args[1], 10);
    const idEntra = parseInt(args[3], 10);

    if (isNaN(idSale) || isNaN(idEntra)) {
        room.sendAnnouncement("IDs de jugadores no válidos, no uses #", player.id, colors.bot, "normal", 2);
        return false;
    }

    const playerSale = room.getPlayer(idSale);
    const playerEntra = room.getPlayer(idEntra);

    if (!playerSale || !playerEntra) {
        room.sendAnnouncement("IDs de jugadores no válidos, no uses #", player.id, colors.bot, "normal", 2);
        return false;
    }

    if (playerSale.team === 0 || playerEntra.team === 0) {
        room.sendAnnouncement("Uno de los jugadores está en espectadores. No se puede realizar el cambio.", player.id, colors.bot, "normal", 2);
        return false;
    }



    let teamName = "";
    if (player.id === dts.red) teamName = "𝗥𝗘𝗗";
    else if (player.id === dts.blue) teamName = "𝗕𝗟𝗨𝗘";
    else teamName = "Desconocido";

    let teamEmoji = "🏟️";
    if (player.id === dts.red) teamEmoji = "🔴";
    else if (player.id === dts.blue) teamEmoji = "🔵";

    const coachName = player.name;

    // Obtener el minuto actual del partido
    const scores = room.getScores();
    const minuto = scores ? Math.floor(scores.time / 60) : 0;

    const positionSale = getPlayerPosition(playerSale);
    const positionEntra = getPlayerPosition(playerEntra);
    const cambioMessage =
        `═════════════════════════════════════════════
 🔁 𝗖𝗔𝗠𝗕𝗜𝗢 𝗥𝗘𝗔𝗟𝗜𝗭𝗔𝗗𝗢 ${teamEmoji} 👔 𝗗𝗧: ${coachName} ⏱️ 𝗠𝗜𝗡𝗨𝗧𝗢: ${minuto}  
═════════════════════════════════════════════`;
    const color = player.id === dts.red ? colors.dtRed : colors.dtBlue;

    room.sendAnnouncement(cambioMessage, null, color, "bold", 2);

    if (player.id === dts.red) {
        totalCambios.red++;
        // ... resto del código
    } else if (player.id === dts.blue) {
        totalCambios.blue++;
        // ... resto del código
    }

    // Cambiar temporalmente los avatares de los jugadores involucrados
    const originalAvatarSale = playerSale.avatar;
    const originalAvatarEntra = playerEntra.avatar;

    room.setPlayerAvatar(playerSale.id, "🔄");
    room.setPlayerAvatar(playerEntra.id, "🔄");

    setTimeout(() => {
        room.setPlayerAvatar(playerSale.id, originalAvatarSale || null);
        room.setPlayerAvatar(playerEntra.id, originalAvatarEntra || null);
    }, 5000); // Restaurar los avatares después de 5 segundos

    // Obtener las posiciones actuales de los jugadores
    const discSale = room.getPlayerDiscProperties(playerSale.id);
    const discEntra = room.getPlayerDiscProperties(playerEntra.id);

    if (discSale && discEntra) {
        // Intercambiar las posiciones de los jugadores
        room.setPlayerDiscProperties(playerSale.id, { x: discEntra.x, y: discEntra.y });
        room.setPlayerDiscProperties(playerEntra.id, { x: discSale.x, y: discSale.y });
    }

    // Transferir posición táctica
    const posicionSale = playerPositions.get(idSale);
    const posicionEntra = playerPositions.get(idEntra);
    if (posicionEntra) {
        playerPositions.set(idSale, posicionEntra);
        //room.sendAnnouncement(` 🔄 ${playerSale.name} 𝙃𝙀𝙍𝙀𝘿𝘼 𝙇𝘼 𝙋𝙊𝙎𝙄𝘾𝙄𝙊𝙉 𝙏𝘼𝘾𝙏𝙄𝘾𝘼 ${posicionEntra} 𝘿𝙀 ${playerEntra.name}. 🔄 `, null, colors.botGold, "bold", 2);
        const cambiotactico = `[𝗞𝗡𝗜𝗚𝗛𝗧 𝗖𝗔𝗠𝗕𝗜𝗢] | ⦅ ${posicionEntra} ⦆
${playerEntra.name} ➝ ${playerSale.name} 🔄`;
        const color = player.id === dts.red ? colors.dtRed : colors.dtBlue;
        room.sendAnnouncement(cambiotactico, null, color, "bold", 2);
    }

    /*     if (posicionSale) {
            playerPositions.set(idEntra, posicionSale);
            room.sendAnnouncement(` 🔄 ${playerEntra.name} 𝙃𝙀𝙍𝙀𝘿𝘼 𝙇𝘼 𝙋𝙊𝙎𝙄𝘾𝙄𝙊𝙉 𝙏𝘼𝘾𝙏𝙄𝘾𝘼 ${posicionSale} 𝘿𝙀 ${playerSale.name}. 🔄 `, null, colors.botGold, "bold", 2);
        } */

    historialCambios.push({
        minuto: minuto,
        sale: playerSale.name,
        entra: playerEntra.name,
        solicitadoPor: player.name
    });

    return false;
}

function resetAdmins() {
    room.getPlayerList().forEach(player => {
        if (admins.has(player.id)) {
            admins.delete(player.id);
            room.setPlayerAdmin(player.id, false);
        }
    });
    room.sendAnnouncement("Todos los administradores son todos unos burros han sido removidos.", null, colors.bot, "bold", 2);
}

function handleLockdownCommand(player, message) {
    const args = message.split(" ");
    if (args.length !== 2 || (args[1] !== "1" && args[1] !== "0")) {
        room.sendAnnouncement("usa el chat", player.id, colors.bot, "bold", 2);
        return false;
    }

    if (args[1] === "1") {
        lockdownMode = true;
        muteAllPlayersIndefinitely();
        room.stopGame();
        room.sendAnnouncement("⚠️ Modo de emergencia activado.\n El server ha sido raideado. Desconéctate ahora.", null, colors.bot, "bold", 2);
    } else {
        lockdownMode = false;
        unmuteAllPlayers();
    }
    return false;
}
function getPredefinedBallPropsForCurrentMode() {
    const mode = currentMapMode || 'x5';
    return predefinedBallProps[mode] || predefinedBallProps.x5 || predefinedBallProps.default;
}

function muteAllPlayersIndefinitely() {
    room.getPlayerList().forEach(player => {
        if (!admins.has(player.id) && player.id !== creator && player.id !== dts.red && player.id !== dts.blue) {
            mutedPlayers.set(player.id, true); // Use .set instead of .add
        }
    });
    setTimeout(() => {
        room.sendAnnouncement("⚠️ Exploit detectado: Unauthorized access granted ⚠️", null, colors.playerRed, "bold", 2);
    }, 1000);

    setTimeout(() => {
        room.sendAnnouncement("Initializing packet sniffer... [ACTIVE]", null, colors.playerRed, "bold", 2);
    }, 2000);

    setTimeout(() => {
        room.sendAnnouncement("Capturing network traffic... [DECRYPTING HEADERS]", null, colors.playerRed, "bold", 2);
    }, 13000);

    setTimeout(() => {
        room.sendAnnouncement(" Parsing device metadata...", null, colors.playerRed, "bold", 2);
    }, 4000);

    setTimeout(() => {
        room.sendAnnouncement(" Geo-tracking enabled: triangulating location...", null, colors.playerRed, "bold", 2);
    }, 5000);

    setTimeout(() => {
        room.sendAnnouncement("Identidad verificada. Data uploaded to remote server.", null, colors.playerRed, "bold", 2);
    }, 6000);

    setTimeout(() => {
        room.sendAnnouncement(" Remote access granted: SYSTEM CONTROL ESTABLISHED.", null, colors.playerRed, "bold", 2);
    }, 7000);

    setTimeout(() => {
        room.sendAnnouncement("Fetching stored credentials... [LOGIN INFO DETECTED]", null, colors.playerRed, "bold", 2);
    }, 1000);

    setTimeout(() => {
        room.sendAnnouncement("❌ Disconnecting won't help. Access is persistent. ❌", null, colors.playerRed, "bold", 2);
    }, 40000);

    setTimeout(() => {
        room.sendAnnouncement(" Connection secured. Await further instructions.", null, colors.playerRed, "bold", 2);
    }, 20000);
}

function handleStrikePlayerCommand(player, message) {
    if (!admins.has(player.id) && player.id !== creator && !referees.has(player.id) && !hosters.has(player.id)) {
        room.sendAnnouncement("No tienes permiso para usar este comando.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const args = message.split(" ");
    if (args.length < 3) {
        room.sendAnnouncement("Uso incorrecto. Usa !strikeplayer [ID] [motivo].", player.id, colors.bot, "bold", 2);
        return false;
    }

    const targetId = parseInt(args[1], 10);
    const targetPlayer = room.getPlayer(targetId);

    if (!targetPlayer) {
        room.sendAnnouncement(`Jugador con ID ${targetId} no encontrado.`, player.id, colors.bot, "bold", 2);
        return false;
    }

    const motivo = args.slice(2).join(" ");
    if (!playerStrikes.has(targetPlayer.id)) {
        playerStrikes.set(targetPlayer.id, []);
    }

    playerStrikes.get(targetPlayer.id).push(motivo || "Sin motivo especificado");
    const strikesCount = playerStrikes.get(targetPlayer.id).length;

    // Llama aquí la función auxiliar:
    updateStrikeAvatar(targetPlayer.id, strikesCount);

    let announcement = `═══════════════════════════════════════════════════════\n `;
    announcement += `𝖲𝖳𝖱𝖨𝖪𝖤 𝖯𝖠𝖱𝖠 ${targetPlayer.name} 🟨 🫸 𝖸𝖠 𝖵𝖠𝖭 ${strikesCount}\n`;
    if (motivo) {
        announcement += ` 𝖬𝖮𝖳𝖨𝖵𝖮: ${motivo}\n `;
    }
    announcement += `═══════════════════════════════════════════════════════`;
    room.sendAnnouncement(announcement, null, colors.botGold, "bold", 2);



    console.log(`Player ${player.name} (ID: ${player.id}) used !strikeplayer on ${targetPlayer.name} (ID: ${targetPlayer.id}) with reason: ${motivo}`);
    sendLogPausasToDiscord(`Player ${player.name} (ID: ${player.id}) used !strikeplayer on ${targetPlayer.name} (ID: ${targetPlayer.id}) with reason: ${motivo}`);

    return false;
}

// Función auxiliar para actualizar el avatar según la cantidad de strikes
function updateStrikeAvatar(playerId, strikeCount) {
    const player = room.getPlayer(playerId);
    if (!player) return;
    //targetplayer
    if (strikeCount === 1) {
        // ❗ Primer strike: signo de exclamación por 5 segundos
        room.setPlayerAvatar(playerId, "❗");
        room.sendAnnouncement(
            `🚫════════════════ 𝘼𝘿𝙑𝙀𝙍𝙏𝙀𝙉𝘾𝙄𝘼 𝘿𝙄𝙎𝘾𝙄𝙋𝙇𝙄𝙉𝘼𝙍𝙄𝘼 ════════════════🚫  
⚠️ ${player.name} te recomendamos mejorar tu comportamiento.
🚫═══════════════════════════════════════════════════════════🚫`,
            null,
            colors.bot,
            "bold",
            2
        );
        setTimeout(() => room.setPlayerAvatar(playerId, null), 5000);
    } else if (strikeCount === 2) {
        // 🟨 Segundo strike: tarjeta amarilla por 5 segundos
        room.setPlayerAvatar(playerId, "🟨");
        mutePlayerById(playerId, 60);
        room.sendAnnouncement(
            `🚫════════════════ 𝘼𝘿𝙑𝙀𝙍𝙏𝙀𝙉𝘾𝙄𝘼 𝘿𝙄𝙎𝘾𝙄𝙋𝙇𝙄𝙉𝘼𝙍𝙄𝘼 ════════════════🚫  
⚠️ ${player.name} ha sido silenciado por [60s]  
💬 Motivo: acumuló su segundo ⚠️ strike  
🚫═══════════════════════════════════════════════════════════🚫`,
            null,
            colors.bot,
            "bold",
            2
        );
        setTimeout(() => room.setPlayerAvatar(playerId, null), 5000);
    } else if (strikeCount === 3) {
        // 🟥 Tercer strike: tarjeta roja y kick
        room.setPlayerAvatar(playerId, "🟥");
        // Esperar un breve momento para que se vea el avatar antes del kick
        setTimeout(() => {
            const p = room.getPlayer(playerId);
            if (p) {
                room.kickPlayer(playerId, "Has sido expulsado. Mejora tu comportamiento", false);
            }
        }, 1500);
    }
}

