function handleAvatarTemporalCommand(player, args) {
    const isVipOrCreator = (player.id === creator) || vips.has(player.id);

    if (!isVipOrCreator) {
        room.sendAnnouncement("Solo los VIP o el creador pueden usar este comando.", player.id, 0xFF0000, "bold", 2);
        return false;
    }

    // Si solo pone "!avatartemporal" sin nada más
    if (args.length === 1) {
        room.sendAnnouncement("Debes escribir el avatar que quieres usar. Ejemplo: !avatartemporal 😎 o !avatartemporal 😎 10 o !avatartemporal 0", player.id, 0xFFDD00, "bold", 2);
        return false;
    }

    // Si pone "!avatartemporal 0" => quitar avatar
    if (args[1] === "0") {
        room.setPlayerAvatar(player.id, null);
        room.sendAnnouncement("Avatar quitado.", player.id, 0x00FF00, "bold", 2);
        // Limpia timeout si existía
        if (avatarTimeouts.has(player.id)) {
            clearTimeout(avatarTimeouts.get(player.id));
            avatarTimeouts.delete(player.id);
        }
        avatarTemporales.delete(player.id); // <-- Aquí 
        return false;
    }

    // Si pone "!avatartemporal (avatar) (tiempo)"
    const avatar = args[1];
    let tiempo = null;
    if (args.length >= 3 && !isNaN(args[2])) {
        tiempo = parseInt(args[2]);
    }

    room.setPlayerAvatar(player.id, avatar);

    if (tiempo && tiempo > 0) {
        const expiresAt = Date.now() + tiempo * 1000;
        avatarTemporales.set(player.id, { avatar, expiresAt });
        room.sendAnnouncement(`Avatar cambiado a: ${avatar} por ${tiempo} segundos.`, player.id, 0x00FF00, "bold", 2);
        // Si ya hay un timeout anterior, lo limpiamos
        if (avatarTimeouts.has(player.id)) {
            clearTimeout(avatarTimeouts.get(player.id));
        }
        // Guardamos el timeout para este jugador
        const timeoutId = setTimeout(() => {
            room.setPlayerAvatar(player.id, null);
            room.sendAnnouncement("Avatar temporal quitado.", player.id, 0x00FF00, "bold", 2);
            avatarTimeouts.delete(player.id);
            avatarTemporales.delete(player.id); // <-- Elimina el registro
        }, tiempo * 1000);
        avatarTimeouts.set(player.id, timeoutId);
    } else {
        room.sendAnnouncement(`Avatar cambiado a: ${avatar}`, player.id, 0x00FF00, "bold", 2);
    }
    return false;
}
function restaurarAvatarTemporal(playerId) {
    const info = avatarTemporales.get(playerId);
    if (!info) return;

    // Si tiene tiempo de expiración, verifica que no haya expirado
    if (info.expiresAt && Date.now() > info.expiresAt) {
        avatarTemporales.delete(playerId);
        return;
    }
    room.setPlayerAvatar(playerId, info.avatar);
}
function handleGolesCommand(player) {
    if (!matchStarted) {
        room.sendAnnouncement("No hay un partido en curso en este momento.", player.id, colors.bot, "bold", 2);
        return;
    }

    // Obtener los goleadores del partido actual
    const currentGoalScorers = Array.from(goalScorers.entries())
        .sort((a, b) => b[1] - a[1]); // Ordenar de más goles a menos

    // Obtener los asistentes del partido actual
    const currentAssistants = Array.from(assistants.entries())
        .sort((a, b) => b[1] - a[1]); // Ordenar de más asistencias a menos

    if (currentGoalScorers.length === 0 && currentAssistants.length === 0) {
        room.sendAnnouncement("No hay goles ni asistencias registradas en el partido actual.", player.id, colors.bot, "bold", 2);
        return;
    }

    let message = "𝙂𝙊𝙇𝙀𝘼𝘿𝙊𝙍𝙀𝙎 𝘿𝙀𝙇 𝙋𝘼𝙍𝙏𝙄𝘿𝙊 𝘼𝘾𝙏𝙐𝘼𝙇\n";
    currentGoalScorers.forEach(([playerName, goals]) => {
        message += `${playerName}: ${goals} 𝙜𝙤𝙡𝙚𝙨\n`;
    });

    message += "\n𝘼𝙎𝙄𝙎𝙏𝙀𝙉𝙏𝙀𝙎 𝘿𝙀𝙇 𝙋𝘼𝙍𝙏𝙄𝘿𝙊 𝘼𝘾𝙏𝙐𝘼𝙇\n";
    currentAssistants.forEach(([playerName, assists]) => {
        message += `${playerName}: ${assists} 𝙖𝙨𝙞𝙨𝙩𝙚𝙣𝙘𝙞𝙖𝙨\n`;
    });

    room.sendAnnouncement(message, player.id, colors.botGold, "bold", 2);
}

function getRandomNumber() {
    const range1 = Array.from({ length: 8 }, (_, i) => i + 1); // 1-8
    const range2 = Array.from({ length: 6 }, (_, i) => i + 9); // 9-14
    const range3 = Array.from({ length: 16 }, (_, i) => i + 15); // 15-30

    const random = Math.random();
    let selectedRange;

    if (random < 0.25) {
        selectedRange = range1;
    } else if (random < 0.85) { // 0.25 + 0.60 = 0.85
        selectedRange = range2;
    } else {
        selectedRange = range3;
    }

    return selectedRange[Math.floor(Math.random() * selectedRange.length)];
}

