function expulsarTemporalmente(playerId, minutos) {
    const player = room.getPlayer(playerId);
    if (!player) return;

    // Detecta el equipo original
    const team = player.team;
    // Pausa el partido
    room.pauseGame(true);

    // Mueve al jugador a espectadores
    room.setPlayerTeam(playerId, 0);

    // Cuenta strikes del equipo
    let equipoStrikes = (team === 1) ? strikes.red.length : strikes.blue.length;
    let equipoNombre = (team === 1) ? "𝗥𝗘𝗗" : "𝗕𝗟𝗨𝗘";
    let colorEquipo = (team === 1) ? colors.playerRed : colors.playerBlue;

    // Anuncio
    room.sendAnnouncement(
        `═══════════════════════════════════════════════════════════
  🔁 𝗦𝗔𝗟𝗘 ${player.name} 𝘆 ${equipoNombre} 𝗦𝗘 𝗤𝗨𝗘𝗗𝗔 -𝟭 🚷
═══════════════════════════════════════════════════════════
        🟨 𝗔𝗖𝗨𝗠𝗨𝗟𝗔𝗡 ${equipoStrikes} 𝗦𝗧𝗥𝗜𝗞𝗘𝗦 🟨
      🕓  ${equipoNombre} -𝟭 ${minutos} 𝗠𝗜𝗡𝗨𝗧𝗢𝗦 🕓
═══════════════════════════════════════════════════════════`,
        null, colorEquipo, "bold"
    );

    // Reanuda el partido después de 3 segundos
    setTimeout(() => {
        room.pauseGame(false);
    }, 3000);

    // Guarda expulsión temporal
    if (expulsionesTemporales.has(playerId)) {
        clearTimeout(expulsionesTemporales.get(playerId).timeoutId);
    }
    expulsionesTemporales.set(playerId, {
        team,
        timeoutId: setTimeout(() => {
            // Devuelve al jugador a su equipo original
            room.setPlayerTeam(playerId, team);
            room.pauseGame(true);
            room.sendAnnouncement(
                `════════════════════════════════════════════
✅🕒 𝗝𝗨𝗚𝗔𝗗𝗢𝗥 𝗛𝗔𝗕𝗜𝗟𝗜𝗧𝗔𝗗𝗢 🕒✅
════════════════════════════════════════════
✅ ${player.name} de ${equipoNombre} vuelve.
════════════════════════════════════════════`,
                null, colorEquipo, "bold"
            );
            setTimeout(() => {
                room.pauseGame(false);
            }, 3000);
            expulsionesTemporales.delete(playerId);
        }, minutos * 60 * 1000)
    });
}

