function setPlayerPosition(player, posicion) {
    // Guardar la posición del jugador en el mapa
    playerPositions.set(player.id, posicion);

    let equipo = "";
    if (player.team === 1) equipo = "🔴 𝗥𝗘𝗗";
    else if (player.team === 2) equipo = "🔵 𝗕𝗟𝗨𝗘";
    else equipo = "⚪ 𝗘𝗦𝗣𝗘𝗖𝗧𝗔𝗗𝗢𝗥";

    // Anunciar la nueva posición del jugador
    room.sendAnnouncement(
        `${player.name} 𝗔𝗛𝗢𝗥𝗔 𝗘𝗦〘 ${posicion} 〙 ${equipo} `, null, player.team === 1 ? colors.dtRed : player.team === 2 ? colors.dtBlue : colors.spectator, "bold", 2);
    //room.sendAnnouncement(`𝗣𝗔𝗥𝗔 𝗖𝗔𝗠𝗕𝗜𝗔𝗥 𝙋𝙊𝙎𝙄𝘾𝙄𝙊𝙉 !𝙂𝙆,!𝘿𝙁𝘾,!𝙈𝘾,!𝘿𝘾`, null, colors.bot, "bold", 2);
}

function getPlayerPosition(player) {
    return playerPositions.get(player.id) || "N/A";
}

function getHosterNames() {
    const hosterNames = [];
    for (const hosterId of hosters) {
        const hosterPlayer = room.getPlayer(hosterId);
        if (hosterPlayer) {
            hosterNames.push(hosterPlayer.name);
        }
    }
    return hosterNames.length > 0 ? hosterNames.join(", ") : "Ninguno";
}

function getPlayerAuth(player) {
    // Si ya tienes el auth en el objeto player
    if (player && player.auth) return player.auth;
    // Si tienes un mapa de id -> auth
    if (player && player.id && playerAuthMap.has(player.id)) return playerAuthMap.get(player.id);
    // Si tienes un cache
    if (player && player.id && cachedAuthById.has(player.id)) return cachedAuthById.get(player.id);
    // Si tienes el auth por nombre (no recomendado, pero por si acaso)
    // ...
    return null;
}
function getPlayerMvpScoregoalScorer(goalScorer,) {
    const playerId = goalScorer.id;
    const stats = goalScorer && goalScorer.stats ? goalScorer.stats : mvpStats[playerId];
    return stats && typeof stats.mvpScore === "number" ? stats.mvpScore.toFixed(2) : "0";
}

function getPlayerMvpScoreassistant(assistant) {
    const playerId = assistant.id;
    const stats = assistant && assistant.stats ? assistant.stats : mvpStats[playerId];
    return stats && typeof stats.mvpScore === "number" ? stats.mvpScore.toFixed(2) : "0";
}
function getPlayerMvpScorePassInitiator(passInitiator) {
    const playerId = passInitiator.id;
    const stats = passInitiator && passInitiator.stats ? passInitiator.stats : mvpStats[playerId];
    return stats && typeof stats.mvpScore === "number" ? stats.mvpScore.toFixed(2) : "0";
}

function getPlayerMvpScore(playerId) {
    const stats = mvpStats[playerId];
    return stats && typeof stats.mvpScore === "number" ? stats.mvpScore.toFixed(2) : "0";
}

function isInBigArea(team, pos) {
    // team: 1 = rojo defiende izquierda, 2 = azul defiende derecha
    if (team === 2) { // Atacando azul (defiende derecha)
        return pos.x <= 650 && pos.x >= 460 && pos.y >= -250 && pos.y <= 250;
    } else { // Atacando rojo (defiende izquierda)
        return pos.x >= -650 && pos.x <= -460 && pos.y >= -250 && pos.y <= 250;
    }
}

function isInSmallArea(team, pos) {
    if (!pos || typeof pos.x !== "number" || typeof pos.y !== "number") {
        // Si pos no está definido o no tiene x/y, retorna false (no está en el área chica)
        return false;
    }
    if (team === 2) {
        return pos.x > 600 && Math.abs(pos.y) < 100;
    } else {
        return pos.x < -600 && Math.abs(pos.y) < 100;
    }
}

room.onPlayerBallKick = function (player) {
    const now = Date.now();
    const ballPos = room.getBallPosition();
    if (!player || !player.id) return;
    //sendLogBallkickToDiscord(`${player.name} (${player.id}) ha pateado el balón`,);
    pendingShots = pendingShots.filter(shot => now - shot.timestamp <= SAVE_WINDOW_MS);
    lastTouchPlayer = player;
    ballTouchHistory.push(player);
    const prevTouchIsRival =
        lastTouchInfo &&
        lastTouchInfo.team !== null &&
        lastTouchInfo.team !== player.team;

    if (!prevTouchIsRival) {
        if (powerShotPlayers.has(player.id)) {
            // Aplica el PowerShot SOLO en el momento del kick
            applyPowerShot(player);
            powerShotPlayers.delete(player.id); // Elimina el PowerShot pendiente
            setTimeout(() => {
                room.setDiscProperties(0, { color: 0xFFFFFF });
            }, 3000);
        }
    }

    if (oneshotmode) {
        // Si el último toque fue del mismo jugador
        if (lastBallTouch.playerId === player.id) {
            // Detener el balón inmediatamente
            room.setDiscProperties(0, { xspeed: 0, yspeed: 0 });

            // Mover a espectadores temporalmente
            const originalTeam = player.team;
            if (originalTeam === 1 || originalTeam === 2) {
                room.setPlayerTeam(player.id, 0); // Mover a espectadores
                room.sendAnnouncement(`${player.name} 𝙉𝙊 𝙋𝙐𝙀𝘿𝙀𝙎 𝙏𝙊𝘾𝘼𝙍 𝙀𝙇 𝘽𝘼𝙇𝙊𝙉 𝟮 𝙑𝙀𝘾𝙀𝙎`, null, colors.bot, "bold", 2);
                setTimeout(() => {
                    room.setPlayerTeam(player.id, originalTeam);
                    room.sendAnnouncement(`${player.name} 𝙃𝘼 𝙑𝙐𝙀𝙇𝙏𝙊 𝘼 ${originalTeam === 1 ? "𝙍𝙀𝘿" : "𝘽𝙇𝙐𝙀"}.`, null, colors.bot, "bold", 2);
                }, 3000);
            }
            // Si tienes lógica de tiro, aquí NO la ejecutas
            return; // Salir de la función para evitar el tiro
        }
    }

    // === VIP BALL KICK CELEBRATION ===
    const playerAuth = playerAuthMap.get(player.id);
    if (playerAuth && vipAvatarBallKick[playerAuth]) {
        const now = Date.now();
        const lastCooldown = vipBallKickCooldown.get(playerAuth) || 0;

        // Verificar cooldown (10 segundos = 10000ms)
        if (now - lastCooldown >= 10000) {
            // Obtener avatar actual del jugador
            const playerProps = room.getPlayer(player.id);
            const currentAvatar = playerProps ? playerProps.avatar : undefined;

            // Guardar avatar actual si no lo hemos guardado
            if (!playerOriginalAvatars.has(player.id)) {
                playerOriginalAvatars.set(player.id, currentAvatar);
            }

            // Aplicar avatar VIP temporalmente
            const vipAvatar = vipAvatarBallKick[playerAuth];
            room.setPlayerAvatar(player.id, vipAvatar);

            // Actualizar cooldown
            vipBallKickCooldown.set(playerAuth, now);

            // Restaurar avatar después de 1000ms
            setTimeout(() => {
                // Verificar que el jugador aún existe antes de restaurar
                if (room.getPlayer(player.id)) {
                    const originalAvatar = playerOriginalAvatars.get(player.id);

                    if (originalAvatar !== undefined && originalAvatar !== null) {
                        room.setPlayerAvatar(player.id, originalAvatar);
                    } else {
                        // Si no existe avatar original, establecer en null explícitamente
                        room.setPlayerAvatar(player.id, null);
                    }
                }
            }, 500); // Delay de 1000ms (1 segundo)
        }
    }

    if (jabulaniActive) stopJabulaniEffect();

    /*     if (jabulaniMode === 1) {
            const ball = room.getDiscProperties(0);
            Jabulani(player, ball);
        } */
    if (!lastBallProps) {
        lastBallProps = room.getDiscProperties(0);
    }
    if (jabulaniMode === JABULANI_MODE) {
        if (jabulaniReady.get(player.id)) {
            const ball = room.getDiscProperties(0);
            Jabulani(player, ball);
            // Ejemplo: aumentar velocidad, cambiar color, etc.
            //room.sendAnnouncement(`⚡ ¡${player.name} dispara el Jabulani!`, null, colors.bot, "bold", 2);
            // ... tu lógica especial ...

            // Consumir el estado
            jabulaniReady.set(player.id, false);
        }
        holdCounter.set(player.id, 0); // Resetear contador
    }

    // --- COMBA CONSUMPTION ---
    if (!prevTouchIsRival) {
        if (combaPlayers.has(player.id)) {
            applyComba(player);
            combaPlayers.delete(player.id);
        }
    }

    lastBallTouch.playerId = player.id;
    lastBallTouch.team = player.team;

    // Limitar el historial a los últimos 10 toques
    if (ballTouchHistory.length > 10) {
        ballTouchHistory.shift();
        //sendLogBallkickToDiscord(`Historial de toques del balón actualizado, se ha eliminado el más antiguo`,);
    }

    const team = player.team;
    if (team === 1) {
        matchStats.redPossession++;
        //sendLogBallkickToDiscord(`El equipo rojo ha tenido la posesión del balón`,);
    } else if (team === 2) {
        matchStats.bluePossession++;
        //sendLogBallkickToDiscord(`El equipo azul ha tenido la posesión del balón`,);
    }

    const stats = mvpStats[player.id];
    if (!stats) return;

    // 1) DRIBBLING
    if (lastTouchInfo && lastTouchInfo.id === player.id) {
        stats.dribbling++;
        //sendLogBallkickToDiscord(`El jugador ${player.name} ha realizado un dribbling`,);
        stats.mvpScore += 0.005;
        if (Math.random() < 0.1) {
            const mvpScore = getPlayerMvpScore(player.id);
            room.sendAnnouncement(`🟢 ❪ +0.05 ❫ 𝙈𝙖𝙣𝙚𝙟𝙤 𝙙𝙚 𝙗𝙖𝙡𝙤𝙣`, player.id, colors.greenpoints, "bold", 0);
            room.sendAnnouncement(` ◈ 𝙨𝙘𝙤𝙧𝙚 (${mvpScore})`, player.id, colors.botGold, "bold", 0);
        }
        //sendLogBallkickToDiscord(`El jugador ${player.name} ha ganado 0.0001 puntos MVP por dribbling`,);
        if (narrador === 1) {
            sendDribbleToNarrator(player);
        }
        //sendLogBallkickToDiscord(`El jugador ${player.name} ha enviado un drible al narrador`,);
    }

    // 2) TOUCH
    stats.touches++;
    //sendLogBallkickToDiscord(`El jugador ${player.name} ha tocado el balón`,);
    stats.mvpScore += 0.005;
    //sendLogBallkickToDiscord(`El jugador ${player.name} ha ganado 0.005 puntos MVP por tocar el balón`,);
    if (narrador === 1) {
        sendTouchToNarrator(player);
    }

    //sendLogBallkickToDiscord(`El jugador ${player.name} ha enviado un toque al narrador`,);

    // 3) BALL RECOVERY
    if (
        lastTouchInfo &&
        lastTouchInfo.team !== player.team &&
        (now - lastRecoveryTime > RECOVERY_COOLDOWN_MS)
    ) {
        stats.ballRecoveries++;
        //sendLogBallkickToDiscord(`El jugador ${player.name} ha recuperado el balón`,);
        stats.mvpScore += 2;
        if (Math.random() < 0.9) {
            const mvpScore = getPlayerMvpScore(player.id);
            room.sendAnnouncement(`🟢 ( +2 ) 𝖨𝖭𝖳𝖤𝖱𝖢𝖤𝖯𝖢𝖨𝖮𝖭 `, player.id, colors.greenpoints, "bold", 0);
            room.sendAnnouncement(` ◈ 𝙨𝙘𝙤𝙧𝙚 (${mvpScore})`, player.id, colors.botGold, "bold", 0);
        }
        //sendLogBallkickToDiscord(`El jugador ${player.name} ha ganado 0.2 puntos MVP por recuperar el balón`,);
        lastRecoveryTime = now;
        //sendLogBallkickToDiscord(`El jugador ${player.name} lastrecovery`,);
    }

    // 4) PASES
    if (
        passInitiator &&
        passInitiator.id !== player.id
    ) {
        if (passInitiator.team === player.team) {
            // Pase completado
            passInitiator.stats.passesCompleted++;
            //sendLogBallkickToDiscord(`El jugador ha completado un pase a ${player.name}`,);
            passInitiator.stats.mvpScore += 2;
            const mvpScore = getPlayerMvpScorePassInitiator(passInitiator);
            room.sendAnnouncement(`🟢 ( ＋2 ) 𝗯𝘂𝗲𝗻 𝗽𝗮𝘀𝗲`, passInitiator.id, colors.greenpoints, "bold", 0);
            room.sendAnnouncement(`◈ ꜱᴄᴏʀᴇ ❪ ${mvpScore}𝗉𝗍𝗌 ❫ `, passInitiator.id, colors.botGold, "bold", 0);
            //sendLogBallkickToDiscord(`El jugador ha ganado 0.2 puntos MVP por completar un pase`,);
            if (narrador === 1) {
                sendPassToNarrator(passInitiator);
            }
            //sendLogBallkickToDiscord(`El jugador ha enviado un pase al narrador`,);
            // DETECTAR PASE LARGO
            if (
                passInitiator.position &&
                player.position
            ) {
                const dx = passInitiator.position.x - player.position.x;
                const dy = passInitiator.position.y - player.position.y;
                const distance = Math.sqrt(dx * dx + dy * dy);
                if (distance >= LONG_PASS_THRESHOLD) {
                    passInitiator.stats.longPasses++;
                    //sendLogBallkickToDiscord(`El jugador ha realizado un pase largo a ${player.name}`,);
                    passInitiator.stats.mvpScore += 3; // bono por pase largo
                    //sendLogBallkickToDiscord(`El jugador ha ganado 0.5 puntos MVP por realizar un pase largo`,);
                    const mvpScore = getPlayerMvpScorePassInitiator(passInitiator);
                    room.sendAnnouncement(`🟢 ( +4 ) 𝗽𝗮𝘀𝗲 𝗹𝗮𝗿𝗴𝗼`, passInitiator.id, colors.greenpoints, "bold", 0);
                    room.sendAnnouncement(`(◈ 𝘴𝘤𝘰𝘳𝘦 ${mvpScore}𝗽𝘁𝘀)`, passInitiator.id, colors.botGold, "bold", 0);

                }
            }
        } else {
            // Pase fallado
            passInitiator.stats.passesFailed++;
            //sendLogBallkickToDiscord(`El jugador ha fallado un pase a ${player.name}`,);
            passInitiator.stats.mvpScore -= 2;
            if (Math.random() < 0.5) {
                const mvpScore = getPlayerMvpScorePassInitiator(passInitiator);
                room.sendAnnouncement(`🔴 ⟨ -2 ⟩ ᴘᴇʀᴅɪᴅᴀ ᴅᴇ ʙᴀʟᴏɴ `, passInitiator.id, colors.redPoints, "bold", 0);
                room.sendAnnouncement(`▸ 𝒔𝒄𝒐𝒓𝒆 (${mvpScore} 𝗽𝘁𝘀)`, passInitiator.id, colors.botGold, "bold", 0);
            }
            //sendLogBallkickToDiscord(`El jugador ha perdido 0.1 puntos MVP por fallar un pase`,);

            if (narrador === 1) {
                sendFailedPassToNarrator(passInitiator, player); // <--- Añade esto
            }
            //sendLogBallkickToDiscord(`El jugador  ha enviado un pase fallido al narrador`,);
        }
    }

    // 1. Limpiar tiros pendientes caducados
    pendingShots = pendingShots.filter(shot => now - shot.timestamp <= SAVE_WINDOW_MS);

    //const ballPos = room.getBallPosition();

    // 2. ¿Es un atacante que patea desde el área grande rival?
    if (player.team === 1 || player.team === 2) {
        const teamAttacked = player.team === 1 ? 2 : 1;
        if (isInBigArea(teamAttacked, ballPos)) {
            if (player && player.id && ballPos && typeof ballPos.x === 'number' && typeof ballPos.y === 'number') {
                //sendLogBallkickToDiscord(`El jugador ${player.name} is in big area`,);
                // Usar ballPos con seguridad
            } else {
                console.warn("Datos inválidos en onPlayerBallKick");
                //sendLogBallkickToDiscord(`Datos inválidos en onPlayerBallKick`,);
                return; // Salir de la función si los datos no son válidos
            }
            // Registrar tiro pendiente
            pendingShots.push({
                shooterId: player.id,
                teamAttacked: teamAttacked,
                ballPos: { x: ballPos.x, y: ballPos.y },
                timestamp: now
            });
            //sendLogBallkickToDiscord(`Tiro pendiente registrado para ${player.name}`,);

            // Asegurarse de que el jugador tenga inicializadas sus estadísticas
            if (!mvpStats[player.id]) initMvpStats(player);

            // Incrementar el contador de tiros (shots) y el puntaje MVP
            mvpStats[player.id].shots = (mvpStats[player.id].shots || 0) + 1;
            //sendLogBallkickToDiscord(` El jugador ${player.name} ha incrementado su contador de tiros`,);
            mvpStats[player.id].mvpScore = (mvpStats[player.id].mvpScore || 0) + 1;
            if (Math.random() < 0.8) {
                const mvpScore = getPlayerMvpScore(player.id);
                room.sendAnnouncement(`🟢 ( +1 ) CHANCE CLARA`, player.id, colors.greenpoints, "bold", 0);
                room.sendAnnouncement(`◈ 𝗌𝖼𝗈𝗋𝖾 ❪ ${mvpScore}𝗉𝗍𝗌 ❫ `, player.id, colors.botGold, "bold", 0);
            }
            //sendLogBallkickToDiscord(`El jugador ${player.name} ha ganado 0.2 puntos MVP por tiro pendiente`,);


            if (narrador === 1) {
                sendShotInBoxToNarrator(player); // <--- Aquí
            }
            //sendLogBallkickToDiscord(`El jugador ${player.name} ha enviado un tiro pendiente al narrador`,);

            // Anunciar tiro pendiente
            handleAreaMessage(player);
            //sendLogBallkickToDiscord(`Anuncio de tiro pendiente enviado para ${player.name}`,);

        }
    }

    const atajadaMessages = [
        "\n 𝗔𝗧𝗔𝗝𝗔𝗗𝗢𝗡 𝗗𝗘 {name} 🧤 \n ",
        "\n ¡𝗤𝗨𝗘 𝗔𝗧𝗔𝗝𝗔𝗗𝗔 𝗗𝗘 {name}! 😱🧤 \n ",
        "\n 𝗦𝗔𝗟𝗩𝗔𝗗𝗔 𝗗𝗘 {name} 🤯 \n ",
        "\n 𝗔𝗧𝗔𝗝𝗔𝗗𝗢𝗡 𝗘𝗦𝗣𝗘𝗖𝗧𝗔𝗖𝗨𝗟𝗔𝗥 𝗗𝗘 {name} 🧤💥 \n ",
        "\n 𝗤𝗨𝗘 𝗠𝗔𝗡𝗢𝗧𝗔𝗭𝗢 𝗗𝗘 {name} 🖐️ \n ",
        "\n 𝗧𝗨 𝗧𝗥𝗔𝗡𝗤𝗨𝗜𝗟𝗢, 𝗗𝗜𝗝𝗢 {name} 🤫 \n ",
        "\n 𝗘𝗦𝗧𝗔𝗦 𝗦𝗢𝗡 𝗟𝗔𝗦 𝗤𝗨𝗘 𝗚𝗔𝗡𝗔𝗡 𝗣𝗔𝗥𝗧𝗜𝗗𝗢𝗦, {name}! 🧤🏆 \n ",
        "\n 𝗔𝗧𝗔𝗝𝗢 {name} !! 🤫 \n"
    ];

    // 3. ¿Es un defensor que toca en su área chica y hay tiro pendiente?
    if (player.team === 1 || player.team === 2) {
        if (player && player.id && ballPos && typeof ballPos.x === 'number' && typeof ballPos.y === 'number') {
            //sendLogBallkickToDiscord(`El jugador ${player.name} is in small area`,);
            // Usar ballPos con seguridad
        } else {
            console.warn("Datos inválidos en onPlayerBallKick");
            //sendLogBallkickToDiscord(`Datos inválidos en onPlayerBallKick`, player.team);
            return; // Salir de la función si los datos no son válidos
        }
        // ¿Está en su propia área chica?
        if (isInSmallArea(player.team, ballPos)) {
            //sendLogBallkickToDiscord(`El jugador ${player.name} está en su área chica`,);
            // ¿Hay tiro pendiente contra su equipo?
            const shotIdx = pendingShots.findIndex(shot => shot.teamAttacked === player.team);
            //sendLogBallkickToDiscord(`Buscando tiro pendiente para el jugador ${player.name}`,);
            if (shotIdx !== -1) {
                //sendLogBallkickToDiscord(`Tiro pendiente encontrado para el jugador ${player.name}`,);
                // Atajada detectada
                if (!mvpStats[player.id]) initMvpStats(player);
                mvpStats[player.id].saves = (mvpStats[player.id].saves || 0) + 1;
                //sendLogBallkickToDiscord(`El jugador ${player.name} ha incrementado su contador de atajadas`,);
                mvpStats[player.id].mvpScore = (mvpStats[player.id].mvpScore || 0) + 8;
                const mvpScore = getPlayerMvpScore(player.id);
                room.sendAnnouncement(`🟢 ( +8 ) 𝘀𝗮𝗹𝘃𝗮𝗱𝗮 ${mvpStats[player.id].name || player.name}`, player.id, colors.greenpoints, "bold", 0);
                room.sendAnnouncement(`〈 MVP 〉 (${mvpScore}) `, player.id, colors.botGold, "bold", 0);
                //sendLogBallkickToDiscord(`El jugador ${player.name} ha ganado 1 punto MVP por atajada`,);
                // Eliminar el tiro pendiente
                pendingShots.splice(shotIdx, 1);
                //sendLogBallkickToDiscord(`Tiro pendiente eliminado para el jugador ${player.name}`,);
                pendingShots = pendingShots.filter(shot => now - shot.timestamp <= SAVE_WINDOW_MS);

                if (narrador === 1) {
                    sendAtajadasToNarrator(player);
                }
                //sendLogBallkickToDiscord(`Tiros pendientes actualizados para el jugador ${player.name}`,);
                // Anunciar la atajada
                //sendLogBallkickToDiscord(`Anuncio de atajada enviado para ${player.name}`,);
                if (justScoredGoal) return; // NO mostrar si acaba de haber gol
                //sendLogBallkickToDiscord(`Enviando mensaje de atajada para ${player.name}`,);
                //room.sendAnnouncement(`\n 𝗔𝗧𝗔𝗝𝗢 ${player.name} !! 🤫 \n `, null, colors.botGold, "bold", 2);
                /* const msg = atajadaMessages[Math.floor(Math.random() * atajadaMessages.length)].replace("{name}",);
                room.sendAnnouncement(msg, null, colors.botGold, "bold", 2);
                sendLogBallkickToDiscord(`Mensaje de atajada: ${msg}`,); */
            }
        }
    }

    if (team !== 1 && team !== 2) return;

    const rivalTeam = team === 1 ? 2 : 1;

    // 1. Detectar pase potencial SOLO si el último toque fue de otro jugador
    if (

        lastTouchInfo && // Hubo un toque anterior
        lastTouchInfo.id !== player.id && // No es el mismo jugador
        lastTouchInfo.team === team && // Es del mismo equipo
        !isInSmallArea(rivalTeam, ballPos) // El pase se origina fuera del área chica rival

    ) {
        //sendLogBallkickToDiscord(`El jugador ${player.name} está haciendo un lastkeypass`,);
        // Guardamos el pase potencial
        lastKeyPass = {
            passerId: lastTouchInfo.id,
            team: team,
            tick: room.getScores()?.time || Date.now()
        };
        //sendLogBallkickToDiscord(`lastkeypass stats guardados para el jugador ${player.name}`,);
    }

    // 2. Detectar recepción y validar pase clave
    if (lastKeyPass) {
        if (player && player.id && ballPos && typeof ballPos.x === 'number' && typeof ballPos.y === 'number') {
            //sendLogBallkickToDiscord(`El jugador ${player.name} está recibiendo un pase clave`,);
            // Usar ballPos con seguridad
        } else {
            //sendLogBallkickToDiscord(`Datos inválidos en onPlayerBallKick para el jugador ${player.name}`,);
            console.warn("Datos inválidos en onPlayerBallKick");
            return; // Salir de la función si los datos no son válidos
        }
        // El jugador que recibe debe ser del mismo equipo, distinto al que pasó
        if (
            player.id !== lastKeyPass.passerId &&
            player.team === lastKeyPass.team &&
            (isInBigArea(rivalTeam, ballPos) || isInSmallArea(rivalTeam, ballPos))
        ) {
            //sendLogBallkickToDiscord(`El jugador ${player.name} ha recibido un pase clave `,);
            // Asegurar que el registro de stats del que pasó exista
            if (!mvpStats[lastKeyPass.passerId]) {
                initMvpStats({ id: lastKeyPass.passerId }); // o crea el objeto manualmente si no usas `initMvpStats`
                //sendLogBallkickToDiscord(`Se ha inicializado el registro de stats para el jugador `,);
            }
            // Evitar duplicados usando tick
            if (lastKeyPass && lastKeyPass.tick !== undefined) {
                if (!mvpStats[lastKeyPass.passerId].lastKeyPassTick ||
                    mvpStats[lastKeyPass.passerId].lastKeyPassTick !== lastKeyPass.tick) {

                    mvpStats[lastKeyPass.passerId].keyPasses = (mvpStats[lastKeyPass.passerId].keyPasses || 0) + 1;
                    //sendLogBallkickToDiscord(`El jugador ha incrementado su contador de pases clave`,);
                    mvpStats[lastKeyPass.passerId].mvpScore = (mvpStats[lastKeyPass.passerId].mvpScore || 0) + 2;
                    if (Math.random() < 0.8) {
                        const mvpScore = getPlayerMvpScore(player.id);
                        room.sendAnnouncement(`🟢 ❪ +𝟮 ❫ 𝖯𝖠𝖲𝖤 𝖢𝖫𝖠𝖵𝖤`, player.id, colors.greenpoints, "bold", 0)
                        room.sendAnnouncement(`〈 MVP 〉 (${mvpScore}) `, player.id, colors.botGold, "bold", 0);;
                    }
                    //sendLogBallkickToDiscord(`El jugador ha ganado 0.2 puntos MVP por pase clave`,);
                    mvpStats[lastKeyPass.passerId].lastKeyPassTick = lastKeyPass.tick;
                    //sendLogBallkickToDiscord(`El jugador ha actualizado su tick de pase clave`,);

                    //room.sendAnnouncement(`${room.getPlayer(lastKeyPass.passerId).name} hizo un pase clave!`, null, 0xFFD700, "bold", 1);
                }
            }
            lastKeyPass = null;
        }
        // Si lo toca un rival, se cancela el pase clave
        if (lastKeyPass && player.team !== lastKeyPass.team) {
            lastKeyPass = null;
            //sendLogBallkickToDiscord(`El pase clave de ha sido cancelado por un rival`,);
        }
    }
    // Guardar info del jugador actual para próximas detecciones
    //sendLogBallkickToDiscord(`Guardando info del jugador ${player.name} para próximas detecciones`,);
    lastTouchInfo = { id: player.id, team: player.team };
    passInitiator = {
        id: player.id,
        team: player.team,
        stats: stats,
        position: player.position // Se usa solo si existe
    };

    if (RealSoccer) {
        Game.rsTouchTeam = player.team;
        Game.updateLastKicker(player.id, player.name, player.team);

        if (Game.rsReady == true) {
            var players = room.getPlayerList().filter((player) => player.team != 0);
            players.forEach(function (player) {
                if (room.getPlayerDiscProperties(player.id).invMass.toFixed(1) != 0.3) {
                    room.setPlayerDiscProperties(player.id, { invMass: 0.3 });
                }
            });
        }

        if (Game.rsActive == false && Game.rsReady == true && (Game.rsCorner == true || Game.rsGoalKick == true)) { // make game active on kick from CK/GK
            Game.boosterState = true;

            Game.rsActive = true;
            Game.rsReady = false;
            room.setDiscProperties(1, { x: 2000, y: 2000 });
            room.setDiscProperties(2, { x: 2000, y: 2000 });
            room.setDiscProperties(0, { color: "0xffffff" });
            Game.rsTimer = 1000000;
            Game.warningCount++;

            // set gravity for real soccer corners/goalkicks
            if (Game.rsCorner == true) {
                if (room.getDiscProperties(0).y < 0) { //top corner
                    room.setDiscProperties(0, { xgravity: room.getPlayerDiscProperties(player.id).xspeed / 35 * -1, ygravity: 0.05 });
                    //room.setDiscProperties(0, {xgravity: -0.08, ygravity: 0.05});
                }
                else { //bottom corner
                    room.setDiscProperties(0, { xgravity: room.getPlayerDiscProperties(player.id).xspeed / 35 * -1, ygravity: -0.05 });
                    //room.setDiscProperties(0, {xgravity: -0.08, ygravity: -0.05});
                }
            }
            if (Game.rsGoalKick == true) {
                room.setDiscProperties(0, { xgravity: 0, ygravity: room.getPlayerDiscProperties(player.id).yspeed / 40 * -1 });
            }

            Game.rsCorner = false;
            Game.rsGoalKick = false;
            Game.outStatus = "";
        }

        if (Game.outStatus == "redThrow" || Game.outStatus == "blueThrow") {
            Game.throwinKicked = true;
        }
    }

    /*let ps = powerShotData[player.id];
    if (!ps) return;
 
    // Si PowerShot está listo y es el primer toque
    if (ps.ready && ps.touches === 0) {
        applyPowerShot(player);
        ps.charges = 0;
        ps.cooldown = true;
        ps.ready = false;
        ps.touches = 1;
        room.sendAnnouncement(`💥 ${player.name} ha usado su PowerShot. ¡Cooldown de 8 minutos!`, player.id, 0xFF4500, "bold", 2);
 
        // Cambia color de la pelota
        let ballProps = room.getDiscProperties(0);
        room.setDiscProperties(0, { color: ColorPowerShot });
 
        // Inicia cooldown
        setTimeout(() => {
            ps.cooldown = false;
            ps.touches = 0;
            // Restaura color de la pelota si nadie más está usando PowerShot
            room.setDiscProperties(0, { color: null });
            room.sendAnnouncement(`✅ ${player.name}, tu PowerShot está listo para recargarse. Corre 500 para cargarlo de nuevo.`, player.id, 0xFF4500, "bold", 2);
        }, PowerShotCooldown);
 
    } else if (ps.touches >= 1) {
        // Si ya usó el PowerShot, no aplica más potencia
        // (Opcional: puedes resetear aquí si quieres)
        resetPowerShot(player);
    }*/

};

function stopJabulaniEffect() {
    if (!jabulaniActive) return;
    jabulaniActive = false;

    // Obtener las propiedades predefinidas para el modo de mapa actual
    const props = getPredefinedBallPropsForCurrentMode() || {};

    // Construir el objeto solo con las propiedades válidas
    const discProps = {};
    if (typeof props.invMass !== "undefined") discProps.invMass = props.invMass;
    if (typeof props.radius !== "undefined") discProps.radius = props.radius;
    if (typeof props.color !== "undefined") discProps.color = props.color;
    if (typeof props.restitution !== "undefined") discProps.restitution = props.restitution;
    if (typeof props.damping !== "undefined") discProps.damping = props.damping;

    // Solo fuerza la gravedad a cero, NO toques la velocidad
    discProps.xgravity = 0;
    discProps.ygravity = 0;

    try {
        room.setDiscProperties(0, discProps);
        room.setDiscProperties(0, { color: 0xFFFFFF });
        savedBallProps = null;
        lastBallProps = null;
        /* room.sendAnnouncement(
            "════════════════════════════ \n ✅⚙️ 𝗕𝗔𝗟𝗢́𝗡 𝗥𝗘𝗦𝗧𝗔𝗨𝗥𝗔𝗗𝗢 ⚙️✅ \n ════════════════════════════ \n Modo actual: " + (currentMapMode || "x5"),
            null, colors.botGold, "bold", 2
        ); */
    } catch (err) {
        room.sendAnnouncement("Error al restaurar el balón: " + err, null, colors.bot, "bold", 2);
    }
    if (jabulaniTimeout) {
        clearTimeout(jabulaniTimeout);
        jabulaniTimeout = null;
    }
    if (jabulaniWallInterval) {
        clearInterval(jabulaniWallInterval);
        jabulaniWallInterval = null;
    }
    lastJabulaniKick = null;
}


function Jabulani(player, ball) {
    if (jabulaniActive) return; // Prevent reapplying
    jabulaniActive = true;

    if (!lastBallProps) {
        lastBallProps = room.getDiscProperties(0);
    }

    if (todosjuegan) {
        JABULANI_CURVE_MULTIPLIER = 8;
    } else if (dtsMode) {
        JABULANI_CURVE_MULTIPLIER = 6;
    } else if (RealSoccer) {
        JABULANI_CURVE_MULTIPLIER = 9;
        JABULANI_SPEED_MULTIPLIER = MULTIPLICADOR_POWERSHOT * 0.9; // 50% del PowerShot
    }
    // Fuerza fija de curvatura
    const CURVE_FORCE = 0.025 * JABULANI_CURVE_MULTIPLIER;

    // Obtén la velocidad inicial del balón
    const vx = ball.xspeed || 0;
    const vy = ball.yspeed || 0;

    // --- BOOST DE VELOCIDAD (50% del PowerShot) ---
    // Calcula la velocidad actual del balón
    let xspeed = ball.xspeed || 0;
    let yspeed = ball.yspeed || 0;
    let speed = Math.sqrt(xspeed * xspeed + yspeed * yspeed);

    // Si el balón está casi detenido, calcula dirección desde el jugador hacia el balón
    if (speed < 0.1) {
        let playerDisc = room.getPlayerDiscProperties(player.id);
        if (playerDisc) {
            let dx = ball.x - playerDisc.x;
            let dy = ball.y - playerDisc.y;
            let dist = Math.sqrt(dx * dx + dy * dy) || 1;
            xspeed = (dx / dist) * JABULANI_SPEED_MULTIPLIER;
            yspeed = (dy / dist) * JABULANI_SPEED_MULTIPLIER;
        }
    } else {
        xspeed *= JABULANI_SPEED_MULTIPLIER;
        yspeed *= JABULANI_SPEED_MULTIPLIER;
    }

    // Aplica la nueva velocidad al balón
    room.setDiscProperties(0, {
        xspeed: xspeed,
        yspeed: yspeed
    });

    // Guarda el signo de la dirección inicial
    const initialSignX = Math.sign(vx);
    const initialSignY = Math.sign(vy);



    // Determina si el disparo es más horizontal o vertical
    let applyXGravity = false;
    let applyYGravity = false;

    if (Math.abs(vx) > Math.abs(vy)) {
        // Disparo horizontal: aplica gravedad en Y
        applyYGravity = true;
    } else {
        // Disparo vertical: aplica gravedad en X
        applyXGravity = true;
    }

    // Dirección aleatoria: + o -
    const curveDirection = Math.random() < 0.5 ? 1 : -1;

    // Prepara las propiedades de curvatura
    let discProps = {};
    if (applyYGravity) {
        discProps = { ygravity: CURVE_FORCE * curveDirection, xgravity: 0 };
    } else if (applyXGravity) {
        discProps = { xgravity: CURVE_FORCE * curveDirection, ygravity: 0 };
    }

    // Cancela el efecto anterior (restaura gravedad normal)
    /*     if (lastJabulaniKick !== null) {
            room.setDiscProperties(0, { xgravity: 0, ygravity: 0 });
        } */
    room.setDiscProperties(0, { xgravity: 0, ygravity: 0 });


    // Aplica el nuevo efecto de curvatura
    room.setDiscProperties(0, discProps);

    // Guarda el último kick para referencia
    lastJabulaniKick = {
        playerId: player.id,
        time: Date.now(),
        discProps: discProps
    };

    // --- Stop after random duration (3-5s) ---
    let randomMs = 500 + Math.floor(Math.random() * 200);
    jabulaniTimeout = setTimeout(stopJabulaniEffect, randomMs);

    if (RealSoccer) {
        randomMs = 700 + Math.floor(Math.random() * 500);
        jabulaniTimeout = setTimeout(stopJabulaniEffect, randomMs);
        FIELD_X = 1030;
        FIELD_Y = 400;
    }
    // --- Wall collision check y cambio de dirección ---
    jabulaniWallInterval = setInterval(() => {
        const ballProps = room.getDiscProperties(0);
        const ballPos = room.getBallPosition();
        const radius = ballProps?.radius || 14;

        // 1. Si toca pared, detén efecto
        if (
            Math.abs(ballPos.x) + radius >= FIELD_X ||
            Math.abs(ballPos.y) + radius >= FIELD_Y
        ) {
            stopJabulaniEffect();
            return;
        }

        // 2. Si cambia de dirección respecto a la inicial, detén efecto
        if (
            (applyYGravity && Math.sign(ballProps.xspeed) !== initialSignX && Math.abs(ballProps.xspeed) > 0.1) ||
            (applyXGravity && Math.sign(ballProps.yspeed) !== initialSignY && Math.abs(ballProps.yspeed) > 0.1)
        ) {
            stopJabulaniEffect();
            return;
        }
        /*     // --- Stop after random duration (3-5s) ---
            const randomMs = 2000 + Math.floor(Math.random() * 1000);
            jabulaniTimeout = setTimeout(stopJabulaniEffect, randomMs);
        
            // --- Wall collision check ---
            jabulaniWallInterval = setInterval(() => {
                const ballProps = room.getDiscProperties(0);
                const ballPos = room.getBallPosition();
                const radius = ballProps?.radius || 10;
                if (
                    Math.abs(ballPos.x) + radius >= FIELD_X ||
                    Math.abs(ballPos.y) + radius >= FIELD_Y
                ) {
                    stopJabulaniEffect();
                } */
    }, 50);
}

function applyComba(player) {
    if (!combaMode) return;

    const ball = room.getDiscProperties(0);
    if (!ball) return;

    const cb = combaData[player.id];
    if (!cb) return;

    if (todosjuegan) {
        JABULANI_CURVE_MULTIPLIER = 8;
        FIELD_Y = 640;
        FIELD_X = 280;
    } else if (dtsMode) {
        JABULANI_CURVE_MULTIPLIER = 6;
    }

    // --- SPEED BOOST (identical to Jabulani: 1.275x) ---
    let xspeed = ball.xspeed || 0;
    let yspeed = ball.yspeed || 0;
    let speed = Math.sqrt(xspeed * xspeed + yspeed * yspeed);

    const vx = ball.xspeed || 0;
    const vy = ball.yspeed || 0;

    if (speed < 0.1) {
        let playerDisc = room.getPlayerDiscProperties(player.id);
        if (playerDisc) {
            let dx = ball.x - playerDisc.x;
            let dy = ball.y - playerDisc.y;
            let dist = Math.sqrt(dx * dx + dy * dy) || 1;
            xspeed = (dx / dist) * JABULANI_SPEED_MULTIPLIER;
            yspeed = (dy / dist) * JABULANI_SPEED_MULTIPLIER;
        }
    } else {
        xspeed *= JABULANI_SPEED_MULTIPLIER;
        yspeed *= JABULANI_SPEED_MULTIPLIER;
    }

    room.setDiscProperties(0, {
        xspeed: xspeed,
        yspeed: yspeed,
        color: 0x2fff00
    });

    // --- CURVE EFFECT (identical to Jabulani) ---
    const initialSignX = Math.sign(vx);
    const initialSignY = Math.sign(vy);

    let applyXGravity = false;
    let applyYGravity = false;

    if (Math.abs(vx) > Math.abs(vy)) {
        applyYGravity = true;
    } else {
        applyXGravity = true;
    }

    const curveDirection = Math.random() < 0.5 ? 1 : -1;
    const CURVE_FORCE = 0.025 * JABULANI_CURVE_MULTIPLIER;

    let discProps = {};
    if (applyYGravity) {
        discProps = { ygravity: CURVE_FORCE * curveDirection, xgravity: 0 };
    } else if (applyXGravity) {
        discProps = { xgravity: CURVE_FORCE * curveDirection, ygravity: 0 };
    }

    room.setDiscProperties(0, discProps);

    // --- COOLDOWN (identical to PowerShot: 300000ms) ---
    cb.cooldown = true;
    cb.lastUsed = Date.now();
    setTimeout(() => {
        cb.cooldown = false;
    }, combaShotCooldown);

    // --- DURATION: 500-700ms random (same as Jabulani) ---
    const randomMs = 500 /* + Math.floor(Math.random() * 200); */
    combaTimeout = setTimeout(() => {
        if (combaWallInterval) {
            clearInterval(combaWallInterval);
            combaWallInterval = null;
        }
        room.setDiscProperties(0, { xgravity: 0, ygravity: 0, color: 0xFFFFFF });
        combaTimeout = null;
    }, randomMs);

    // --- WALL COLLISION CHECK (identical to Jabulani) ---
    combaWallInterval = setInterval(() => {
        const ballProps = room.getDiscProperties(0);
        const ballPos = room.getBallPosition();
        const radius = ballProps?.radius || 14;

        if (
            Math.abs(ballPos.x) + radius >= FIELD_X ||
            Math.abs(ballPos.y) + radius >= FIELD_Y
        ) {
            if (combaTimeout) {
                clearTimeout(combaTimeout);
                combaTimeout = null;
            }
            clearInterval(combaWallInterval);
            combaWallInterval = null;
            room.setDiscProperties(0, { xgravity: 0, ygravity: 0, color: 0xFFFFFF });
            return;
        }

        if (
            (applyYGravity && Math.sign(ballProps.xspeed) !== initialSignX && Math.abs(ballProps.xspeed) > 0.1) ||
            (applyXGravity && Math.sign(ballProps.yspeed) !== initialSignY && Math.abs(ballProps.yspeed) > 0.1)
        ) {
            if (combaTimeout) {
                clearTimeout(combaTimeout);
                combaTimeout = null;
            }
            clearInterval(combaWallInterval);
            combaWallInterval = null;
            room.setDiscProperties(0, { xgravity: 0, ygravity: 0, color: 0xFFFFFF });
            return;
        }
    }, 50);
}


function updateLives(targetId, delta) {
    // Verificar si el jugador existe
    const target = room.getPlayer(targetId);
    if (!target) {
        room.sendAnnouncement(`⚠️ El jugador con ID ${targetId} no existe.`, null, 0xFFFF00, "bold");
        return false;
    }

    // Verificar si el jugador tiene vidas registradas
    if (!playerLives.has(targetId)) {
        room.sendAnnouncement(`⚠️ ${target.name} no tiene vidas registradas.`, null, 0xFFFF00, "bold");
        return false;
    }

    // Actualizar las vidas del jugador
    const currentLives = playerLives.get(targetId);
    const newLives = currentLives + delta;

    // Asegurarse de que las vidas no sean negativas
    playerLives.set(targetId, Math.max(newLives, 0));

    // Anunciar el cambio de vidas
    room.sendAnnouncement(
        `❤️ ${target.name} ahora tiene ${playerLives.get(targetId)} vidas.`,
        null,
        0x00FF00,
        "bold"
    );

    // Si el jugador se queda sin vidas, moverlo a espectadores
    if (playerLives.get(targetId) === 0) {
        room.setPlayerTeam(targetId, 0); // Mover a espectadores
        room.sendAnnouncement(
            `💀 ${target.name} se quedó sin vidas y fue movido a espectadores.`,
            null,
            0xFF0000,
            "bold"
        );
    }

    return true;
}

function AvatarShowLives(player) {
    // Verificar permisos del jugador
    if (player.id !== creator && !admins.has(player.id) && !hosters.has(player.id)) {
        room.sendAnnouncement("⛔ No tienes permiso para usar este comando.", player.id, 0xFF0000, "bold");
        return false;
    }

    const players = room.getPlayerList();
    if (!players || players.length === 0) {
        room.sendAnnouncement("⚠️ No hay jugadores en la sala.", player.id, 0xFFFF00, "bold");
        return false;
    }

    // Mostrar las vidas de los jugadores
    players.forEach(p => {
        const lives = playerLives.get(p.id); // Usar `get` para Map
        if (lives != null) {
            room.setPlayerAvatar(p.id, String(lives));
        }
    });

    room.sendAnnouncement("👁 Mostrando vidas durante 10 segundos...", player.id, 0x00FF00, "bold");

    // Restaurar los avatares después de 10 segundos
    setTimeout(() => {
        players.forEach(p => room.setPlayerAvatar(p.id, null));
    }, 10000);

    return true;
}

function avatarIds() {
    room.getPlayerList().forEach(player => {
        const playerId = player.id.toString(); // Obtener el ID del jugador como cadena

        // Cambiar el avatar del jugador a su ID
        room.setPlayerAvatar(player.id, playerId);

        // Restaurar el avatar a null después de 5 segundos
        setTimeout(() => {
            if (player.id === dts.red) {
                room.setPlayerAvatar(player.id, "👔"); // Restaurar avatar de DT rojo
            } else if (player.id === dts.blue) {
                room.setPlayerAvatar(player.id, "👔"); // Restaurar avatar de DT azul
            } else {
                room.setPlayerAvatar(player.id, null);
            }
        }, 15000);
    });
}

// Función para obtener el número de jugadores en el campo
function getPlayersInField() {
    const players = room.getPlayerList();
    if (!players) return 0;
    return players.filter(player => player.team !== 0).length; // Filtra jugadores que no están en el equipo espectador
}

// Función para cambiar el mapa dinámicamente
function updateRamboMap() {
    if (!RamboMode) return; // Solo ejecuta si RamboMode está activado

    const playersInField = getPlayersInField();
    const stadium = RamboStadiums.find(s => s.key === playersInField.toString());

    if (stadium) {
        room.stopGame(); // Detener el partido actual
        room.setCustomStadium(stadium.data); // Cambiar el mapa
        room.startGame(); // Iniciar un nuevo partido
        room.sendAnnouncement(`⚡ Mapa cambiado a: ${stadium.key} jugadores en campo.`, null, colors.botGold, "bold", 2);
    }
}

