function updateTodosJueganMap() {
    if (!todosjuegan) return;
    if (matchON) return;
    if (!Array.isArray(TJStadiums) || !room || typeof room.setCustomStadium !== "function") {
        room && room.sendAnnouncement("❌ Error: Configuración de estadios o room inválida.", null, colors.botGold, "bold", 2);
        return;
    }

    const currentTime = Date.now();
    const timeSinceLastUpdate = currentTime - lastMapUpdateTime;

    // Verificar cooldown
    if (timeSinceLastUpdate < MAP_UPDATE_COOLDOWN) {
        const remainingTime = Math.ceil((MAP_UPDATE_COOLDOWN - timeSinceLastUpdate) / 1000);
        return;
    }

    // Obtener cantidad de jugadores en el campo
    const playersInField = typeof getPlayersInField === "function" ? getPlayersInField() : 0;

    // Buscar la configuración del estadio para esta cantidad de jugadores
    const stadiumConfig = TJStadiums.find(s => String(s.key) === String(playersInField));

    if (!stadiumConfig || !stadiumConfig.variants || stadiumConfig.variants.length === 0) {
        room.sendAnnouncement(`⚠️ No hay mapas disponibles para ${playersInField} jugadores.`, null, colors.botGold, "bold", 2);
        return;
    }

    try {
        // Seleccionar una variante aleatoria
        const randomVariant = stadiumConfig.variants[Math.floor(Math.random() * stadiumConfig.variants.length)];

        if (!randomVariant || !randomVariant.data) {
            room.sendAnnouncement("❌ Error: Datos del mapa inválidos.", null, colors.botGold, "bold", 2);
            return;
        }

        // Cambiar el mapa
        room.stopGame();
        room.setCustomStadium(randomVariant.data);
        room.startGame();

        room.sendAnnouncement(
            `⚡ Mapa actualizado para ${stadiumConfig.key} jugadores (Variante ${Math.floor(Math.random() * stadiumConfig.variants.length) + 1})`,
            null,
            colors.botGold,
            "bold",
            2
        );

        lastMapUpdateTime = currentTime;
    } catch (err) {
        room.sendAnnouncement(`❌ Error al cambiar el mapa: ${err.message}`, null, colors.botGold, "bold", 2);
    }
}

function updatefutsalMap() {
    if (!futsalMode) return;

    const playerCount = room.getPlayerList().length;

    if (futsalMode && x3 && playerCount > 6) {
        console.log("Futsal 3v3 mode: Más de 6 jugadores, no se cambia el mapa.");
        return;
    }
    console.log("updatefutsalMap: Cambiando mapa según jugadores en campo.");

    const currentTime = Date.now();
    const timeSinceLastUpdate = currentTime - lastMapUpdateTime;

    if (timeSinceLastUpdate < MAP_UPDATE_COOLDOWN) {
        const remainingTime = Math.ceil((MAP_UPDATE_COOLDOWN - timeSinceLastUpdate) / 1000);
        //room.sendAnnouncement(`⏱️ Espera ${remainingTime}s para cambiar el mapa.`, null, colors.botRed, "bold", 1);
        return;
    }

    const playersInField = getPlayersInField();
    const stadium = FutsalStadiums.find(s => s.key === playersInField.toString());

    if (stadium) {
        room.stopGame(); // Detener el partido actual
        room.setCustomStadium(stadium.data); // Cambiar el mapa
        if (!pickInProcess) {
            room.startGame(); // Iniciar un nuevo partido
            console.log(`partido iniciado no hay pick en proceso`);
        }
        room.sendAnnouncement(`⚡ Mapa cambiado a: ${stadium.key} jugadores en campo.`, null, colors.botGold, "bold", 2);
        lastMapUpdateTime = currentTime;
    }
}

