function obtenerAvataresPersonalizados(player) {
    if (!player) {
        return null;
    }
    const auth = playerAuthMap.get(player.id);
    if (auth && avataresPersonalizados.has(auth)) {
        return avataresPersonalizados.get(auth);
    }
    if (avataresPersonalizados.has(player.id)) {
        return avataresPersonalizados.get(player.id);
    }
    return null;
}

function isValidAutogoal(lastTouch, secondLastTouch, ballPosition, team) {
    // Si el último toque fue del equipo defensor, en su área chica, y el penúltimo fue rival
    if (
        lastTouch && lastTouch.team === team &&
        isInSmallArea(team, lastTouch.pos) &&
        secondLastTouch && secondLastTouch.team !== team
    ) {
        // NO es autogol, es gol del rival (penúltimo toque)
        return false;
    }
    // En cualquier otro caso, sí es autogol
    return true;
}

// Modificar la función cambiarAvataresTemporalmente para usar obtenerAvataresPersonalizados
function cambiarAvataresTemporalmente(goalScorer, assistant, team, opponentTeam) {
    const DURACION_TOTAL = 5000;
    const INTERVALO_CAMBIO = 1000;
    let ciclos = 0;
    const maxCiclos = DURACION_TOTAL / INTERVALO_CAMBIO;

    const avataresOriginales = new Map();
    const estadosAvatares = new Map();

    /* // Obtener los emojis personalizados o usar los predeterminados
    const goalScorerEmojis = obtenerAvataresPersonalizados(goalScorer) || ["⚽️", "GG", "EZ", "🤌"];
    const assistantEmojis = obtenerAvataresPersonalizados(assistant) || ["🅰️", "🗿", "🔟", "👌"]; */

    const goalScorerEmojiGroups = [
        ["⚽️", "GG", "EZ", "🤌"],
        ["😁", "🫰", "🤫", "🚷"],
        ["🐐", "🏆", "💪", "🤣"],
        ["🗿", "🫶", "👏", "👻"],
    ];
    const assistantEmojiGroups = [
        ["🅰️", "🗿", "🔟", "👌"],
        ["🎩", "✋", "🤝", "🪄"],
        ["👟", "⚽️", "🧎🏼‍♂️", "😹"],
        ["🫵", "🫡", "🏃", "🙌"],
    ];

    const goalScorerEmojis = obtenerAvataresPersonalizados(goalScorer) || goalScorerEmojiGroups[Math.floor(Math.random() * goalScorerEmojiGroups.length)];
    const assistantEmojis = obtenerAvataresPersonalizados(assistant) || assistantEmojiGroups[Math.floor(Math.random() * assistantEmojiGroups.length)];

    const configurarAvatar = (player, avatarEspecial) => {
        if (!player) return;
        if (!player.id) {
            console.error(`Error: El jugador ${player.name} no tiene un ID válido`);
            return;
        }
        avataresOriginales.set(player.id, player.avatar);
        estadosAvatares.set(player.id, {
            original: player.avatar,
            especial: avatarEspecial,
            mostrarEspecial: true
        });
        room.setPlayerAvatar(player.id, avatarEspecial);
    };

    if (goalScorer) configurarAvatar(goalScorer, goalScorerEmojis[0]);
    if (assistant) configurarAvatar(assistant, assistantEmojis[0]);

    const dtRival = team === 1 ? room.getPlayer(dts.blue) : room.getPlayer(dts.red);
    if (dtRival) configurarAvatar(dtRival, "🤬");
    const dtPropio = team === 1 ? room.getPlayer(dts.red) : room.getPlayer(dts.blue);
    if (dtPropio) configurarAvatar(dtPropio, "👏"); // O el avatar que prefieras

    const avatars = ["☠️", "💩", "😓", "❓", "💀", "😤", "😐", "😬", "😵‍💫", "-5", "-1", "🫠", "🫩"];
    const avatarsPropios = ["🔥", "💪", "👏", "👀", "👌", "👆", "👈", "👉", "👍", "🗣"];

    room.getPlayerList().forEach(player => {
        if (player.team === opponentTeam && player.id !== (dtRival?.id || null)) {
            const randomAvatar = avatars[Math.floor(Math.random() * avatars.length)];
            configurarAvatar(player, randomAvatar);
        }
    });

    // Cambiar avatares de los jugadores del equipo que hizo el gol (excepto DT propio)
    room.getPlayerList().forEach(player => {
        if (player.team === team && player.id !== (dtPropio?.id || null)) {

            // Verificar si es goleador o asistente
            const isGoalScorer = goalScorer && goalScorer.id === player.id;
            const isAssistant = assistant && assistant.id === player.id;

            // Obtener avatares personalizados (si existen)
            const goalScorerEmojis = isGoalScorer ? obtenerAvataresPersonalizados(goalScorer) : null;
            const assistantEmojis = isAssistant ? obtenerAvataresPersonalizados(assistant) : null;

            // LÓGICA: Ignorar SOLO si tienen avatares personalizados
            if (isGoalScorer && goalScorerEmojis) return; // Tiene avatar personalizado, ignorar
            if (isAssistant && assistantEmojis) return;   // Tiene avatar personalizado, ignorar

            const randomAvatar = avatarsPropios[Math.floor(Math.random() * avatarsPropios.length)];
            configurarAvatar(player, randomAvatar);
        }
    });


    const intervalo = setInterval(() => {
        ciclos++;

        estadosAvatares.forEach((estado, id) => {
            const player = room.getPlayer(id);
            if (!player) return;

            let nuevoAvatar;
            if (id === goalScorer?.id) {
                nuevoAvatar = goalScorerEmojis[ciclos % goalScorerEmojis.length];
            } else if (id === assistant?.id) {
                nuevoAvatar = assistantEmojis[ciclos % assistantEmojis.length];
            } else if (player.team === opponentTeam) {
                nuevoAvatar = estado.mostrarEspecial ? estado.especial : estado.original;
            } else {
                nuevoAvatar = estado.mostrarEspecial ? estado.original : estado.especial;
            }

            room.setPlayerAvatar(id, nuevoAvatar);
            estadosAvatares.set(id, {
                ...estado,
                mostrarEspecial: !estado.mostrarEspecial
            });
        });

        if (ciclos >= maxCiclos) {
            clearInterval(intervalo);
            avataresOriginales.forEach((avatar, id) => {
                const player = room.getPlayer(id);
                if (player) {
                    if (avatarTemporales.has(player.id)) {
                        restaurarAvatarTemporal(player.id);
                    } else {
                        room.setPlayerAvatar(player.id, avatar || null);
                    }
                }
            });
        }
    }, INTERVALO_CAMBIO);
}

function celebracionGrupalVIP(goalScorer, assistant, team, opponentTeam) {
    const DURACION_TOTAL = 5000;
    const INTERVALO_CAMBIO = 1000;
    let ciclos = 0;
    const maxCiclos = DURACION_TOTAL / INTERVALO_CAMBIO;

    // Emojis para grupo secundario (no sincronizado)
    const avatarsPropios = ["🔥", "💪", "👏", "👀", "👌", "👆", "👈", "👉", "👍", "🗣"];

    // Emojis para equipo rival
    const avatarsRival = ["☠️", "💩", "😓", "❓", "💀", "😤", "😐", "😬", "😵‍💫", "-5", "-1", "🫠", "🫩"];


    // Obtener auth del goleador para los emojis sincronizados
    const goalScorerAuth = getPlayerAuth(goalScorer);
    //const emojiGroup = vipGroupCelebration[goalScorerAuth] || ["⚽️", "🎯", "🔥", "💥"];
    //const emojiGroup = vipGroupCelebration[goalScorerAuth] || obtenerAvataresPersonalizados(goalScorer) || ["⚽️", "🎯", "🔥", "💥"];
    const emojiGroup = vipGroupCelebration[goalScorerAuth]

    const avataresOriginales = new Map();
    const estadosAvatares = new Map();
    let vipIndex = 0;

    // ============================================
    // EQUIPO QUE ANOTÓ: Lógica VIP
    // ============================================

    // Obtener todos los jugadores del equipo (excluir DT)
    const dtPropio = team === 1 ? room.getPlayer(dts.red) : room.getPlayer(dts.blue);
    const teamPlayers = room.getPlayerList().filter(p =>
        p.team === team &&
        p.id !== (dtPropio?.id || null)
    );

    // Calcular tamaño del grupo VIP (80%)
    const vipGroupSize = Math.max(2, Math.floor(teamPlayers.length * 0.8));

    // Crear grupo VIP: incluir goalScorer y assistant al inicio
    const grupoVIP = [];
    const grupoSecundario = [];

    // Asegurar que goalScorer está en VIP
    if (goalScorer && teamPlayers.some(p => p.id === goalScorer.id)) {
        grupoVIP.push(goalScorer);
    }

    // Asegurar que assistant está en VIP (si existe y es del equipo)
    if (assistant && assistant.team === team && teamPlayers.some(p => p.id === assistant.id)) {
        if (!grupoVIP.some(p => p.id === assistant.id)) {
            grupoVIP.push(assistant);
        }
    }

    // Llenar grupo VIP con jugadores restantes hasta alcanzar 80%
    for (const player of teamPlayers) {
        if (grupoVIP.length >= vipGroupSize) break;
        if (!grupoVIP.some(p => p.id === player.id)) {
            grupoVIP.push(player);
        }
    }

    // Resto va al grupo secundario
    for (const player of teamPlayers) {
        if (!grupoVIP.some(p => p.id === player.id)) {
            grupoSecundario.push(player);
        }
    }

    // ============================================
    // CONFIGURAR AVATARES INICIALES
    // ============================================

    const configurarAvatar = (player, avatarEspecial) => {
        if (!player || !player.id) return;
        avataresOriginales.set(player.id, player.avatar);
        estadosAvatares.set(player.id, {
            original: player.avatar,
            especial: avatarEspecial,
            mostrarEspecial: true,
            tipo: 'default'
        });
        room.setPlayerAvatar(player.id, avatarEspecial);
    };

    // Grupo VIP: emoji inicial
    grupoVIP.forEach(p => configurarAvatar(p, emojiGroup[0]));

    // Grupo secundario: emojis aleatorios
    grupoSecundario.forEach(p => {
        const randomAvatar = avatarsPropios[Math.floor(Math.random() * avatarsPropios.length)];
        configurarAvatar(p, randomAvatar);
    });

    // DT propio: avatar especial
    if (dtPropio) configurarAvatar(dtPropio, "👏");

    // ============================================
    // EQUIPO RIVAL: Comportamiento actual
    // ============================================

    const dtRival = team === 1 ? room.getPlayer(dts.blue) : room.getPlayer(dts.red);

    room.getPlayerList().forEach(player => {
        if (player.team === opponentTeam && player.id !== (dtRival?.id || null)) {
            const randomAvatar = avatarsRival[Math.floor(Math.random() * avatarsRival.length)];
            configurarAvatar(player, randomAvatar);
        }
    });

    if (dtRival) configurarAvatar(dtRival, "🤬");

    // ============================================
    // LOOP PRINCIPAL DE ANIMACIÓN
    // ============================================

    const intervalo = setInterval(() => {
        ciclos++;
        vipIndex = (ciclos - 1) % emojiGroup.length;
        const vipEmoji = emojiGroup[vipIndex];

        estadosAvatares.forEach((estado, id) => {
            const player = room.getPlayer(id);
            if (!player) return;

            let nuevoAvatar;

            // Grupo VIP: sincronizado
            if (grupoVIP.some(p => p.id === id)) {
                nuevoAvatar = vipEmoji;
            }
            // Grupo secundario: alternancia individual
            else if (grupoSecundario.some(p => p.id === id)) {
                nuevoAvatar = estado.mostrarEspecial ? estado.especial : estado.original;
            }
            // Rival: alternancia individual
            else if (player.team === opponentTeam) {
                nuevoAvatar = estado.mostrarEspecial ? estado.especial : estado.original;
            }
            // DTs: alternancia
            else {
                nuevoAvatar = estado.mostrarEspecial ? estado.especial : estado.original;
            }

            room.setPlayerAvatar(id, nuevoAvatar);

            // Actualizar estado para grupo secundario y rival
            if (!grupoVIP.some(p => p.id === id)) {
                estadosAvatares.set(id, {
                    ...estado,
                    mostrarEspecial: !estado.mostrarEspecial
                });
            }
        });

        // Terminar animación y restaurar avatares
        if (ciclos >= maxCiclos) {
            clearInterval(intervalo);

            avataresOriginales.forEach((avatar, id) => {
                const player = room.getPlayer(id);
                if (player) {
                    if (avatarTemporales.has(id)) {
                        restaurarAvatarTemporal(id);
                    } else {
                        room.setPlayerAvatar(id, avatar || null);
                    }
                }
            });
        }
    }, INTERVALO_CAMBIO);
}


