/**
 * ────────────────────────────────────────────────────────────────
 * P7: af4StartGame() - Inicia un partido AF4v4
 * ────────────────────────────────────────────────────────────────
 * Lógica:
 *   1. Verifica si AF4v4mode está activo
 *   2. Cuenta jugadores en cancha vs totales
 *   3. Configura score limit y time limit
 *   4. Selecciona mapa según cantidad de jugadores
 *   5. Si >= 9 jugadores: modo pick
 *   6. Si < 9 jugadores: mixTeams() + autobalance + startGame
 */
function af4StartGame() {
    if (!AF4v4mode) return;

    const playerCount = room.getPlayerList().length;
    if (matchON && playerCount <= 8) return;
    console.log("[AF4v4] af4StartGame llamado — jugadores en sala:", playerCount);
    // RESETS iniciales de estado residual
    af4MatchTime = 0;
    af4EligibleList = [];
    af4PendingMoves.clear();
    af4RedPicked = false;

    console.log("[AF4v4] af4StartGame iniciado");
    af4DiagnosticarEstado();

    // Conteo de jugadores (solo los que NO son espectadores)
    const allPlayers = room.getPlayerList();
    const inField = allPlayers.filter(p => p.team !== 0);
    const totalInSala = allPlayers.length;

    // El total relevante: SIEMPRE totalInSala (no depende de inField)
    const total = totalInSala;
    console.log("[AF4v4] Jugadores en sala:", totalInSala, "| en cancha:", inField.length);

    // SIEMPRE primero: setScoreLimit y setTimeLimit
    room.setScoreLimit(3);
    room.setTimeLimit(4);

    // Seleccionar mapa según cantidad
    let mapKey;
    if (total <= 4) mapKey = "1";
    else if (total <= 6) mapKey = "6";
    else mapKey = "8";

    const stadium = FutsalStadiums.find(s => s.key === mapKey);
    if (stadium) {
        try {
            room.setCustomStadium(stadium.data);
            console.log("[AF4v4] Mapa cargado, key:", mapKey);
        } catch (e) {
            console.error("[AF4v4] Error cargando mapa:", e);
        }
    }

    if (total >= 9) {
        // Modo pick
        console.log("[AF4v4] 9+ jugadores → modo pick");
        af4StartPickTurn();
    } else {
        // Partido normal con autobalance
        console.log("[AF4v4] <9 jugadores → partido normal");

        // ━━━ EDGE CASE 1: Todos en specs, equipos vacíos, <9 jugadores ━━━
        const redCount = af4CountTeam(1);
        const blueCount = af4CountTeam(2);
        if (redCount === 0 && blueCount === 0) {
            console.log("[AF4v4] Edge: todos en specs <9 → mixTeams + startGame");
        }

        mixTeams();
        initialReBalance();
        // initialTeamsBalance y autoBalanceTeams se activan (P6)
        room.startGame();
    }
}

// ════════════════════════════════════════════════════════════════════════════
// ═ AF4v4mode - FUNCIONES UTILITARIAS DE PICKING                             ═
// ════════════════════════════════════════════════════════════════════════════

/**
 * Registra un movimiento pendiente de jugador
 * Llamar INMEDIATAMENTE después de room.setPlayerTeam()
 * @param {number} playerId - ID del jugador
 * @param {number} teamId - Team ID (0=spec, 1=red, 2=blue)
 */
function af4RegisterMove(playerId, teamId) {
    if (teamId === 0) {
        af4PendingMoves.delete(playerId);
    } else {
        af4PendingMoves.set(playerId, teamId);
    }
    console.log("[AF4v4] PendingMove registrado:", playerId, "→ equipo", teamId);
}

/**
 * Conteo confiable de un equipo durante el pick
 * Incluye jugadores confirmados + pendientes
 * @param {number} teamId - Team ID (1=red, 2=blue)
 * @returns {number} Total de jugadores en el equipo
 */
function af4CountTeam(teamId) {
    const players = room.getPlayerList();

    const confirmed = players
        .filter(p => p.team === teamId)
        .map(p => p.id);

    const pending = [...af4PendingMoves.entries()]
        .filter(([id, t]) => {
            if (t !== teamId) return false;
            const player = players.find(p => p.id === id);
            if (!player) return false;
            if (player.team !== 0 && player.team !== teamId) return false;
            return true;
        })
        .map(([id]) => id);

    const merged = new Set(confirmed);
    pending.forEach(id => merged.add(id));

    console.log("[AF4v4] af4CountTeam(", teamId, ") →", merged.size);
    return merged.size;
}

/**
 * ────────────────────────────────────────────────────────────────
 * af4VerifyAndStart() - Verifica si se completó 4v4 e inicia partido
 * ────────────────────────────────────────────────────────────────
 * Flujo:
 *   1. Verifica flag anti-doble (af4StartingGame)
 *   2. Limpia timers de pick y setea af4PickPhase en false
 *   3. Cuenta jugadores finales en Red y Blue
 *   4. Si 4v4 exacto: espera 150ms y valida nuevamente
 *   5. Si validación passa: anuncia y llama room.startGame()
 *   6. Si falla: reinicia pick turn
 */
function af4VerifyAndStart() {
    if (af4StartingGame) {
        console.log("[AF4v4] af4VerifyAndStart ya en progreso, skip");
        return;
    }
    af4StartingGame = true;
    console.log("[AF4v4] af4VerifyAndStart ejecutado");

    // Limpieza de timers de pick
    clearTimeout(af4PickTimerWarn);
    clearTimeout(af4PickTimerKick);
    af4PickPhase = false;
    af4PickerActual = null;
    af4EquipoPick = null;

    const red = af4CountTeam(1);
    const blue = af4CountTeam(2);
    console.log("[AF4v4] VerifyAndStart — Red:", red, "Blue:", blue);

    if (red === 4 && blue === 4) {
        af4PendingMoves.clear();

        // Validación dura final (HaxBall ya debería haber sincronizado)
        setTimeout(() => {
            const finalPlayers = room.getPlayerList();
            const finalRed = finalPlayers.filter(p => p.team === 1).length;
            const finalBlue = finalPlayers.filter(p => p.team === 2).length;
            console.log("[AF4v4] Validación final — Red:", finalRed, "Blue:", finalBlue);

            if (finalRed === 4 && finalBlue === 4) {
                room.sendAnnouncement(
                    "═══════════════════════════\n🏟️ ¡4v4 COMPLETO! INICIANDO PARTIDO…\n═══════════════════════════",
                    null, 0x00FF88, "bold", 2
                );
                if (af4IsPaused) {
                    af4ResumeAfterRepick();
                } else {
                    room.startGame();
                }
            } else {
                console.warn("[AF4v4] Validación fallida, reiniciando pick");
                af4StartingGame = false;
                af4StartPickTurn();
            }
        }, 150);
    } else {
        console.warn("[AF4v4] No hay 4v4 exacto, reiniciando pick. Red:", red, "Blue:", blue);
        af4StartingGame = false;
        af4StartPickTurn();
    }
}

/**
 * Construye la lista de jugadores elegibles para pick
 * Excluye: jugadores en equipos, AFK, ya movidos (pending)
 * @returns {Array<{id, name}>} Lista de jugadores elegibles
 */
function buildEligibleList() {
    const players = room.getPlayerList();
    const eligible = players.filter(p => {
        if (p.team !== 0) return false;              // ya en un equipo
        if (afkPlayers.has(p.id)) return false;      // es AFK
        if (af4PendingMoves.has(p.id)) return false; // ya fue movido (pending)
        return true;
    }).map(p => ({ id: p.id, name: p.name }));

    console.log("[AF4v4] buildEligibleList:", eligible.map(e => e.name));
    return eligible;
}

/**
 * ────────────────────────────────────────────────────────────────
 * handlePickerAfk(player) - Maneja AFK del picker durante AF4v4
 * ────────────────────────────────────────────────────────────────
 * Lógica:
 *   1. Valida que estemos en AF4v4mode + af4PickPhase + sea el picker actual
 *   2. Mueve picker AFK a espectadores (team 0)
 *   3. Limpia timers y estado del pick
 *   4. Anuncia el cambio con emoji 💤
 *   5. Reinicia af4StartPickTurn() después de 200ms
 */
function handlePickerAfk(player) {
    if (!AF4v4mode || !af4PickPhase) return;
    if (!af4PickerActual || af4PickerActual.id !== player.id) return;

    console.log("[AF4v4] Picker se volvió AFK:", player.name);

    const equipoAnterior = af4EquipoPick;
    const idAnterior = af4PickerActual.id;

    // Mover picker AFK a espectadores
    room.setPlayerTeam(idAnterior, 0);
    af4RegisterMove(idAnterior, 0);
    af4PendingMoves.delete(idAnterior);
    af4EligibleList = af4EligibleList.filter(p => p.id !== idAnterior);

    // Resetear estado de pick
    clearTimeout(af4PickTimerWarn);
    clearTimeout(af4PickTimerKick);
    af4PickerActual = null;
    af4EquipoPick = null;
    af4PickPhase = false;

    room.sendAnnouncement(
        `💤 ${player.name} se fue AFK durante el pick. Turno reasignado.`,
        null, 0xFFAA00, "bold", 2
    );
    console.log("[AF4v4] Pick reasignado tras AFK del picker");

    setTimeout(() => af4StartPickTurn(), 200);
}

/**
 * Función de diagnóstico para monitorear el estado del AF4v4mode
 * Llamar al inicio de af4StartPickTurn() y af4StartGame() para debug
 */
function af4DiagnosticarEstado() {
    const players = room.getPlayerList();
    const red = players.filter(p => p.team === 1).map(p => p.name);
    const blue = players.filter(p => p.team === 2).map(p => p.name);
    const specs = players.filter(p => p.team === 0).map(p => p.name);
    console.log("[AF4v4] Estado actual:");
    console.log("  Red:", red);
    console.log("  Blue:", blue);
    console.log("  Specs:", specs);
    console.log("  Picker:", af4PickerActual?.name, "| Equipo:", af4EquipoPick);
    console.log("  EligibleList:", af4EligibleList.map(e => e.name));
    console.log("  PendingMoves:", [...af4PendingMoves.entries()]);
    console.log("  af4MatchTime:", af4MatchTime);
    console.log("  af4PickPhase:", af4PickPhase);
}

/**
 * Inicia la fase de pick automático para AF4v4
 * Asigna al primer jugador elegible si un equipo está vacío
 * Cede el turno de pick al primer jugador del equipo en construcción
 */
function af4StartPickTurn() {
    if (!AF4v4mode) return;
    const totalEnSala = room.getPlayerList().length;
    if (totalEnSala < 9) {
        console.log("[AF4v4] af4StartPickTurn abortado — menos de 9 jugadores:", totalEnSala);
        setTimeout(() => af4StartGame(), 200);
        return;
    }
    console.log("[AF4v4] af4StartPickTurn iniciado");
    af4DiagnosticarEstado();

    // Limpiar estado anterior del pick
    clearTimeout(af4PickTimerWarn);
    clearTimeout(af4PickTimerKick);
    af4PendingMoves.clear();
    af4PickerActual = null;
    af4EquipoPick = null;
    af4PickPhase = false;

    const redCount = af4CountTeam(1);
    const blueCount = af4CountTeam(2);
    console.log("[AF4v4] Pick — Red:", redCount, "| Blue:", blueCount);

    // Verificar si ya están completos (edge case)
    if (redCount === 4 && blueCount === 4) {
        console.log("[AF4v4] 4v4 ya completos, verificando inicio");
        af4VerifyAndStart();
        return;
    }

    // ━━━ EDGE CASE 2: 9+ pero specs no-AFK disponibles para completar sin pick ━━━
    const nonAfkSpecs = buildEligibleList();
    const needed = (4 - redCount) + (4 - blueCount);
    if (nonAfkSpecs.length === needed && needed > 0) {
        console.log("[AF4v4] Edge: completando equipos automáticamente sin pick");
        // Completar red primero, luego blue
        let assignedCount = 0;
        const toAssign = [
            ...nonAfkSpecs.slice(0, 4 - redCount).map(p => ({ player: p, team: 1 })),
            ...nonAfkSpecs.slice(4 - redCount).map(p => ({ player: p, team: 2 }))
        ];

        toAssign.forEach((item, index) => {
            setTimeout(() => {
                const player = item.player;
                const team = item.team;
                room.setPlayerTeam(player.id, team);
                af4RegisterMove(player.id, team);
                assignedCount++;
                console.log("[AF4v4] Auto-asignado:", player.name, "→ equipo", team, "(", assignedCount, "/", needed, ")");

                if (assignedCount === needed) {
                    setTimeout(() => af4VerifyAndStart(), 100);
                }
            }, index * 80);
        });
        return;
    }

    // ── Determinar quién pickea ──────────────────────────────
    // Red siempre primero

    if (redCount < 4) {
        if (redCount === 0) {
            // No hay nadie en red: primer elegible de specs pasa a red y pickea
            const elegibles = buildEligibleList();
            if (elegibles.length === 0) {
                room.sendAnnouncement("⚠️ No hay jugadores elegibles para completar Red.", null, 0xFF4444, "bold", 2);
                return;
            }
            const nuevoRed = elegibles[0];
            // ORDEN OBLIGATORIO: primero síncrono, luego setTimeout
            room.setPlayerTeam(nuevoRed.id, 1);
            af4RegisterMove(nuevoRed.id, 1);
            setTimeout(() => {
                af4PickerActual = nuevoRed;
                af4EquipoPick = 1;
                af4PickPhase = true;
                af4EligibleList = buildEligibleList();

                // ✓ Check: si el equipo quedó completo al mover el picker
                const faltanRed = 4 - af4CountTeam(1);
                if (faltanRed === 0) {
                    console.log("[AF4v4] Picker completa el equipo solo — sin turno de pick necesario");
                    af4PickPhase = false;
                    af4RedPicked = true;
                    setTimeout(() => af4StartPickTurn(), 100);  // Pasar a Blue
                    return;
                }

                af4AnunciarPick();
                af4StartPickTimer();
            }, 80);
        } else {
            // Red tiene 1–3 jugadores: getFirstPlayer(1) pickea para completar red
            const picker = getFirstPlayer(1);
            if (!picker) {
                console.error("[AF4v4] No se encontró primer jugador de Red");
                return;
            }
            setTimeout(() => {
                af4PickerActual = picker;
                af4EquipoPick = 1;
                af4PickPhase = true;
                af4EligibleList = buildEligibleList();

                // ✓ Check: si el equipo quedó completo al mover el picker
                const faltanRed = 4 - af4CountTeam(1);
                if (faltanRed === 0) {
                    console.log("[AF4v4] Picker completa el equipo solo — sin turno de pick necesario");
                    af4PickPhase = false;
                    af4RedPicked = true;
                    setTimeout(() => af4StartPickTurn(), 100);  // Pasar a Blue
                    return;
                }

                af4AnunciarPick();
                af4StartPickTimer();
            }, 80);
        }
    } else {
        // Red tiene 4: turno de Blue
        if (!af4RedPicked) af4RedPicked = true;
        const elegibles = buildEligibleList();
        if (elegibles.length === 0) {
            room.sendAnnouncement("⚠️ No hay jugadores elegibles para Blue.", null, 0xFF4444, "bold", 2);
            return;
        }
        const nuevoBlue = elegibles[0];
        room.setPlayerTeam(nuevoBlue.id, 2);
        af4RegisterMove(nuevoBlue.id, 2);
        setTimeout(() => {
            af4PickerActual = nuevoBlue;
            af4EquipoPick = 2;
            af4PickPhase = true;
            af4EligibleList = buildEligibleList();

            // ✓ Check: si el equipo quedó completo al mover el picker
            const faltanBlue = 4 - af4CountTeam(2);
            if (faltanBlue === 0) {
                console.log("[AF4v4] Picker completa el equipo solo — sin turno de pick necesario");
                af4PickPhase = false;
                af4VerifyAndStart();
                return;
            }

            af4AnunciarPick();
            af4StartPickTimer();
        }, 80);
    }
}

/**
 * Anuncia la lista de jugadores elegibles al chat
 * Se envía un mensaje público con los números del 1 al N
 */
function af4AnunciarPick() {
    const equipo = af4EquipoPick === 1 ? "🔴 RED" : "🔵 BLUE";
    const faltan = 4 - af4CountTeam(af4EquipoPick);
    let msg = `════════════════════════\n${equipo} — ${af4PickerActual.name} ELIGE (faltan ${faltan})\nEscribe el número del jugador:\n`;
    af4EligibleList.forEach((p, i) => {
        msg += `${i + 1}. ${p.name}\n`;
    });
    msg += "⏳ Tienes 30s — aviso a los 15s\n════════════════════════";
    room.sendAnnouncement(msg, null, af4EquipoPick === 1 ? 0xFF4444 : 0x4444FF, "bold", 2);
    console.log("[AF4v4] Lista de pick anunciada para:", af4PickerActual.name);
}

/**
 * Inicia el sistema de timer para el turno de pick (15s warn, 30s kick)
 * Completamente independiente del timer AFK de partido
 */
function af4StartPickTimer() {
    clearTimeout(af4PickTimerWarn);
    clearTimeout(af4PickTimerKick);

    console.log("[AF4v4] Timer de pick iniciado para:", af4PickerActual?.name);

    af4PickTimerWarn = setTimeout(() => {
        if (!af4PickPhase || !af4PickerActual) return;
        room.sendAnnouncement(
            `⚠️ ${af4PickerActual.name} ¡TIENES 15 SEGUNDOS PARA ELEGIR!`,
            null, 0xFFAA00, "bold", 0
        );
        console.log("[AF4v4] Warn de pick enviado a:", af4PickerActual?.name);
    }, 15000);

    af4PickTimerKick = setTimeout(() => {
        if (!af4PickPhase || !af4PickerActual) return;
        const kickedId = af4PickerActual.id;
        const kickedName = af4PickerActual.name;
        const equipoPick = af4EquipoPick;
        console.log("[AF4v4] Kick por timeout de pick:", kickedName);

        // Mover picker de vuelta a specs y kickear
        room.setPlayerTeam(kickedId, 0);
        af4RegisterMove(kickedId, 0);
        af4PendingMoves.delete(kickedId);

        room.sendAnnouncement(
            `⏰ ${kickedName} fue kickeado por no elegir a tiempo.`,
            null, 0xFF4444, "bold", 2
        );
        room.kickPlayer(kickedId, "Tiempo de pick agotado", false);

        // Resetear picker actual
        af4PickerActual = null;
        af4EquipoPick = null;
        af4PickPhase = false;

        // El siguiente picker del mismo equipo (se resolverá en af4StartPickTurn)
        console.log("[AF4v4] Reasignando pick al siguiente de equipo:", equipoPick);
        setTimeout(() => af4StartPickTurn(), 200);
    }, 30000);
}

/**
 * Reinicia el timer de pick sin reanuenciar ni reconstruir lista
 * Se llama SINCRÓNICAMENTE en onPlayerChat después de cada pick válido
 */
function af4ResetPickTimer() {
    // Solo reinicia el timer, no reconstruye la lista ni anuncia
    clearTimeout(af4PickTimerWarn);
    clearTimeout(af4PickTimerKick);
    af4StartPickTimer();
    console.log("[AF4v4] Timer de pick reiniciado");
}

// ════════════════════════════════════════════════════════════════════════════

function af4Normalize() {
    af4ResetInProgress = true;
    console.log("[AF4v4] af4Normalize iniciado");

    // 1. Limpiar timers de pick
    clearTimeout(af4PickTimerWarn);
    clearTimeout(af4PickTimerKick);
    af4PickTimerWarn = null;
    af4PickTimerKick = null;

    // 2. Limpiar timers de partido
    clearInterval(af4MatchInterval);
    af4MatchInterval = null;
    af4MatchTime = 0;

    // 3. Limpiar estado de pick
    af4PickPhase = false;
    af4PickerActual = null;
    af4EquipoPick = null;
    af4EligibleList = [];
    af4PendingMoves.clear();
    af4RedPicked = false;
    af4StoppingGame = false;
    af4StartingGame = false;
    af4RepickInProgress = false;
    af4EarlyStop = false;  // Limpieza segura del flag

    // 4. Si hay partido activo, detenerlo
    if (matchON) {
        console.log("[AF4v4] af4Normalize: deteniendo partido activo");
        room.stopGame();
        // onGameStop detectará af4ResetInProgress === true y hará return inmediato
    } else {
        af4ResetInProgress = false;
        console.log("[AF4v4] af4Normalize completo (sin partido activo)");
        af4StartGame();
    }
}

/**
 * ────────────────────────────────────────────────────────────────
 * startAFMatchTimer() - Inicia el contador de tiempo del partido AF4v4
 * ────────────────────────────────────────────────────────────────
 * Sistema de medición completamente independiente del timer de pick (P11).
 * Solo mide si pasaron los primeros 30 segundos del partido (umbral early-leave).
 */
function startAFMatchTimer() {
    clearInterval(af4MatchInterval);
    af4MatchTime = 0;
    console.log("[AF4v4] Timer de partido iniciado");

    af4MatchInterval = setInterval(() => {
        if (!matchON || !AF4v4mode) {
            clearInterval(af4MatchInterval);
            return;
        }
        af4MatchTime++;
        // Detener el conteo en 31 (solo necesitamos saber si pasó 30s)
        if (af4MatchTime >= 31) {
            clearInterval(af4MatchInterval);
            console.log("[AF4v4] Timer detenido en 31s (umbral alcanzado)");
        }
    }, 1000);
}

/**
 * ────────────────────────────────────────────────────────────────
 * isEarlyLeave() - Determina si el abandono fue temprano
 * ────────────────────────────────────────────────────────────────
 * Retorna true si el abandono ocurrió antes de 30 segundos.
 * Solo cuenta jugadores en cancha (red + blue), no espectadores.
 */
function isEarlyLeave() {
    // true si el abandono ocurrió antes de 30s
    // Solo cuenta jugadores en cancha (red + blue), no espectadores
    const result = af4MatchTime < 30;
    console.log("[AF4v4] isEarlyLeave:", result, "(af4MatchTime:", af4MatchTime, ")");
    return result;
}

/**
 * ────────────────────────────────────────────────────────────────
 * af4ResumeAfterRepick() - Reanuda partido tras repick por abandono
 * ────────────────────────────────────────────────────────────────
 * Se llama cuando ambos equipos están completos DURANTE una pausa
 * por abandono tardío. En lugar de startGame, reanuda el partido.
 */
function af4ResumeAfterRepick() {
    const finalPlayers = room.getPlayerList();
    const finalRed = finalPlayers.filter(p => p.team === 1).length;
    const finalBlue = finalPlayers.filter(p => p.team === 2).length;

    if (finalRed === 4 && finalBlue === 4) {
        console.log("[AF4v4] Repick tardío completo — reanudando partido");
        room.sendAnnouncement("▶️ ¡EQUIPO COMPLETO! Reanudando partido…", null, 0x00FF88, "bold", 2);
        af4PickPhase = false;
        af4PendingMoves.clear();
        af4IsPaused = false;
        af4RepickInProgress = false;
        room.unpauseGame();
    } else {
        console.warn("[AF4v4] Validación fallida post-repick tardío. Continuando pick.");
        af4StartPickTurn();
    }
}

function updateGlobalStatsAfterMatch(mvpStats, officialMatch) {
    // 1. Load existing rankings
    let rankings = getRankings() || {};

    // 2. Loop through each player in mvpStats
    for (let auth in mvpStats) {
        if (!mvpStats.hasOwnProperty(auth)) continue;
        let stats = mvpStats[auth];

        // 3. If player doesn't exist in rankings, create with default values
        if (!rankings[auth]) {
            rankings[auth] = {
                lastName: stats.name || "",
                totalGoals: 0,
                totalAssists: 0,
                totalSaves: 0,
                matchesPlayed: 0,
                matchesWon: 0,
                mvpScore: 0,
                winRate: 0
            };
        }

        // 4. Add mvpStats to globalStats fields
        rankings[auth].totalGoals += stats.goals || 0;
        rankings[auth].totalAssists += stats.assists || 0;
        rankings[auth].totalSaves += stats.saves || 0;
        rankings[auth].matchesPlayed += stats.played || 1; // Default to 1 if not provided
        rankings[auth].matchesWon += stats.won || 0;
        rankings[auth].mvpScore += stats.mvpScore || 0;

        // 5. Update lastName from mvpStats.name
        rankings[auth].lastName = stats.name || rankings[auth].lastName;

        // 6. Recalculate winRate
        rankings[auth].winRate = rankings[auth].matchesPlayed > 0
            ? Math.round((rankings[auth].matchesWon / rankings[auth].matchesPlayed) * 100)
            : 0;
    }

    // 7. Save updated rankings
    saveRankings(rankings);
}

function mixTeams() {

    let redPlayers = [];
    let bluePlayers = [];
    let spectators = [];

    // Clasificar jugadores
    room.getPlayerList().forEach(player => {  // ✅ CORRECTO: getPlayerList (L mayúscula)
        if (player.team === 1) {
            redPlayers.push(player);
        } else if (player.team === 2) {
            bluePlayers.push(player);
        } else {
            spectators.push(player);
        }
    });

    // Validaciones
    if (redPlayers.length === 0 || bluePlayers.length === 0) {
        room.sendAnnouncement("❌ Necesitas al menos 1 jugador por equipo", null, 0xFF0052, "bold");
        return;
    }

    /*     if (redPlayers.length !== bluePlayers.length) {
            room.sendAnnouncement("⚠️ Los equipos no tienen el mismo número de jugadores", null, 0xFF6A00, "bold");
            return;
        } */

    // Combinar y mezclar
    let allPlayers = [...redPlayers, ...bluePlayers];

    // Fisher-Yates Shuffle
    for (let i = allPlayers.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [allPlayers[i], allPlayers[j]] = [allPlayers[j], allPlayers[i]];
    }

    const teamSize = Math.floor(allPlayers.length / 2); // 🔧 ARREGLO 1: Usar floor
    let newRed = allPlayers.slice(0, teamSize);
    let newBlue = allPlayers.slice(teamSize);

    // Asignar equipos
    newRed.forEach(player => room.setPlayerTeam(player.id, 1));
    newBlue.forEach(player => room.setPlayerTeam(player.id, 2));

    setTimeout(() => {
        // Anunciar con estilo
        room.sendAnnouncement("╔═══════════════╗", null, colors.bot, "bold");
        room.sendAnnouncement("    EQUIPOS", null, colors.botGold, "bold");
        room.sendAnnouncement("╚═══════════════╝", null, colors.bot, "bold");

        room.sendAnnouncement("\n🔴 ROJO (" + newRed.length + " jugadores):\n" +
            newRed.map(p => "  • " + p.name).join("\n"), null, 0xFF5D5D, "normal");

        room.sendAnnouncement("\n🔵 AZUL (" + newBlue.length + " jugadores):\n" +
            newBlue.map(p => "  • " + p.name).join("\n"), null, 0x8ED3EE, "normal");
    }, 15000);

}

function balanceTeams() {
    // Guard: Bloquear durante pick en AF4v4mode
    if (AF4v4mode && af4PickPhase) {
        console.log("[AF4v4] autoBalance bloqueado durante pick");
        return;
    }

    const playerCount = room.getPlayerList().length;

    let mode = null;
    let tope = null;
    if (futsalMode === true && (playerCount > 7 && x3 === true)) {
        mode = "null"; // No hacer rebalance si hay más de 6 jugadores en x3
    } else if (dtsMode) {
        mode = "dtsMode";
    } else if (RealSoccer) {
        mode = "RealSoccer";
    } else if (todosjuegan) {
        mode = "todosjuegan";
    }
    // Si el modo no es válido o el tope es null, salir
    if (!mode) {
        return;
    } else if (dtsMode || RealSoccer) {
    }
    const players = room.getPlayerList();
    let redCount = 0;
    let blueCount = 0;

    // Count the number of players in each team, excluding AFK players
    players.forEach(player => {
        if (afkPlayers.has(player.id)) return; // Skip AFK players
        if (referees.has(player.id)) return; // Saltar referees
        if (player.team === 1) {
            redCount++;
        } else if (player.team === 2) {
            blueCount++;
        }
    });

    // Move players from spectators to the team with fewer players, excluding AFK players
    players.forEach(player => {
        if (afkPlayers.has(player.id)) return; // Skip AFK players
        if (referees.has(player.id)) return; // Saltar referees
        if (player.team === 0) {
            if (redCount < blueCount) {
                room.setPlayerTeam(player.id, 1);
                redCount++;
            } else if (blueCount < redCount) {
                room.setPlayerTeam(player.id, 2);
                blueCount++;
            } else {
                room.setPlayerTeam(player.id, 1);
                redCount++;
            }
        }
    });
}

function initialReBalance() {
    // Determinar el modo activo y el tope de jugadores
    let mode = null;
    let tope = null;

    const playerCount = room.getPlayerList().length;

    if (futsalMode === true && (playerCount <= 6 && x3 === true)) {
        mode = "futsalModex3";
        tope = RBALANCE_CONFIG[mode];
        console.log("initialReBalance: modo futsalModex3 activado");
    } else if (futsalMode === true && (playerCount > 7 && x3 === true)) {
        mode = null; // No hacer rebalance si hay más de 6 jugadores en x3
        tope = null;
        console.log("initialReBalance: modo futsalModex3 con más de 6 jugadores, no se aplica rebalance");
    } else if (futsalMode === true && (typeof x4 !== "undefined" && x4 === true)) {
        mode = "futsalModex4";
        tope = RBALANCE_CONFIG[mode];
        console.log("initialReBalance: modo futsalModex4 activado");
    } else if (futsalMode === true && (typeof x5 !== "undefined" && x5 === true)) {
        mode = "futsalModex5";
        tope = RBALANCE_CONFIG[mode];
        console.log("initialReBalance: modo futsalModex5 activado");
    } else if (typeof fifa3dmode !== "undefined" && fifa3dmode === true) {
        mode = "fifa3dmode";
        tope = RBALANCE_CONFIG[mode];
        console.log("initialReBalance: modo fifa3dmode activado");
    } else if (typeof RamboModeStart !== "undefined" && RamboModeStart === true) {
        mode = "RamboModeStart";
        tope = RBALANCE_CONFIG[mode];
        console.log("initialReBalance: modo RamboModeStart activado");
    } else if (typeof todosjuegan !== "undefined" && todosjuegan === true) {
        mode = "todosjuegan";
        tope = RBALANCE_CONFIG[mode];
        console.log("initialReBalance: modo todosjuegan activado");
    } else if (AF4v4mode === true && (playerCount <= 8)) {
        mode = "AF4v4mode";
        tope = RBALANCE_CONFIG[mode];
        console.log("initialReBalance: modo AF4v4mode con 8 o menos jugadores");
    }
    //tope = RBALANCE_CONFIG[mode];

    //room.sendAnnouncement(`DEBUG: mode=${mode}, tope=${tope}, futsalMode=${futsalMode}, x4=${x4}, x5=${x5}, fifa3dmode=${fifa3dmode}, RamboModeStart=${RamboModeStart}`);

    // Si el modo no es válido o el tope es null, salir
    if (mode == null || tope == null) {
        console.log("initialReBalance: modo no válido o tope es null, no se aplica rebalance.");
        return;
    }
    console.log(`initialReBalance: modo=${mode}, tope=${tope}`);
    const perTeam = Math.floor(tope / 2);

    // Obtener listas de jugadores por equipo
    const players = room.getPlayerList();
    const red = players.filter(p => p.team === 1);
    const blue = players.filter(p => p.team === 2);
    const spectators = players.filter(p => p.team === 0);

    // --- AGREGAR JUGADORES SI FALTAN ---
    // Mientras algún equipo tenga menos de perTeam, mover de spectators
    let redCount = red.length;
    let blueCount = blue.length;
    let specIndex = 0;

    while ((redCount < perTeam || blueCount < perTeam) && specIndex < spectators.length) {
        console.log(`initialReBalance: redCount=${redCount}, blueCount=${blueCount}, specIndex=${specIndex}`);

        // Llenar primero el equipo con menos jugadores
        if (redCount < blueCount && redCount < perTeam) {
            console.log(`initialReBalance: agregando a RED desde espectadores: ${spectators[specIndex].name}`);
            room.setPlayerTeam(spectators[specIndex].id, 1);
            redCount++;
        } else if (redCount < perTeam && redCount <= blueCount) {
            room.setPlayerTeam(spectators[specIndex].id, 1);
            redCount++;
            console.log(`initialReBalance: redCount ahora es ${redCount}`);
        } else if (blueCount < perTeam) {
            console.log(`initialReBalance: agregando a BLUE desde espectadores: ${spectators[specIndex].name}`);
            room.setPlayerTeam(spectators[specIndex].id, 2);
            blueCount++;
            console.log(`initialReBalance: blueCount ahora es ${blueCount}`);
        }
        specIndex++;
        console.log(`initialReBalance: después de mover, redCount=${redCount}, blueCount=${blueCount}, specIndex=${specIndex}`);
        // Detener si ambos equipos están llenos
        if (redCount >= perTeam && blueCount >= perTeam) break;
        console.log(`initialReBalance: ciclo while continúa, redCount=${redCount}, blueCount=${blueCount}, specIndex=${specIndex}`);
    }

    // --- SACAR JUGADORES SI SOBRAN ---
    // Si hay más de perTeam, sacar desde el final de la lista
    if (redCount > perTeam) {
        console.log(`initialReBalance: redCount antes de sacar=${redCount}, perTeam=${perTeam}`);
        // Ordenar por join order si tienes esa info, si no, usar como están
        for (let i = red.length - 1; i >= 0 && redCount > perTeam; i--) {
            room.setPlayerTeam(red[i].id, 0);
            redCount--;
            console.log(`initialReBalance: sacando a ${red[i].name} de RED, redCount ahora es ${redCount}`);
        }
    }
    if (blueCount > perTeam) {
        for (let i = blue.length - 1; i >= 0 && blueCount > perTeam; i--) {
            room.setPlayerTeam(blue[i].id, 0);
            blueCount--;
            console.log(`initialReBalance: sacando a ${blue[i].name} de BLUE, blueCount ahora es ${blueCount}`);
        }
    }
}

function autoBalanceTeams() {
    if (autoBalanceEnabled) {
        balanceTeams();
    }
}

function initialTeamsBalance() {

    const playerCount = room.getPlayerList().length;

    // Guard: Bloquear durante pick en AF4v4mode
    if (AF4v4mode && af4PickPhase) {
        console.log("[AF4v4] autoBalance bloqueado durante pick");
        return;
    }
    if (AF4v4mode && playerCount > 8) {
        console.log("[AF4v4] autoBalance bloqueado");
        return;
    }

    // ============================================
    // 1. VERIFICAR CONDICIONES DE ACTIVACIÓN
    // ============================================

    let shouldExecute = false;
    let currentMode = null;
    let isDynamicMode = false; // NEW: Flag para modos dinámicos

    // Condición 1: futsalMode + (x4 o x5)
    if (futsalMode && (x4 || x5)) {
        shouldExecute = true;
        currentMode = x4 ? "futsalModex4" : "futsalModex5";
        console.log("initialTeamsBalance futsalMode con x4 o x5 activado");
    }

    if (futsalMode && x3 && playerCount <= 6) {
        shouldExecute = true;
        currentMode = "futsalModex3";
        console.log("initialTeamsBalance futsalMode con x3 activado 6 jugadores o menos");
    } else if (futsalMode && x3 && playerCount > 7) {
        shouldExecute = false;
        currentMode = "futsalModex3";
        console.log("initialTeamsBalance futsalMode con x3 activado mas de 6 jugadores, no se aplica balance");
    }


    // Condición 2: fifa3dmode
    if (fifa3dmode) {
        shouldExecute = true;
        currentMode = "fifa3dmode";
    }

    // Condición 3: RamboModeStart
    if (RamboModeStart) {
        shouldExecute = true;
        currentMode = "RamboModeStart";
    }

    if (todosjuegan) {
        shouldExecute = true;
        currentMode = "todosjuegan";
        isDynamicMode = true; // NEW: Marcar como modo dinámico
    }


    if (AF4v4mode && playerCount <= 8) {
        shouldExecute = true;
        currentMode = "AF4v4mode";
        console.log("initialTeamsBalance AF4v4mode activado con 7 jugadores o menos");
    }


    // Si ningún modo está activo, no hacer nada
    if (!shouldExecute || !currentMode) {
        return;
    }

    if (!shouldExecute) {
        return;
    }

    // ============================================
    // 2. VERIFICAR MÍNIMO DE JUGADORES
    // ============================================

    const minimumPlayers = RBALANCE_CONFIG[currentMode];
    const playerList = room.getPlayerList();
    const totalPlayersRoom = playerList.length;

    // Si el mínimo es null, significa que no aplica el balance
    if (minimumPlayers === null && !isDynamicMode) {
        return;
    }

    // Si hay más jugadores que el mínimo requerido, no ejecutar balance
    if (minimumPlayers !== null && totalPlayersRoom > minimumPlayers) {
        return;
    }

    // ============================================
    // 3. CONTAR JUGADORES POR EQUIPO
    // ============================================

    const players = playerList; // Cambio aquí
    const redPlayers = players.filter(p => p.team === 1); // Team RED
    const bluePlayers = players.filter(p => p.team === 2); // Team BLUE

    const redCountRoom = redPlayers.length;
    const blueCountRoom = bluePlayers.length;

    // ============================================
    // 4. VERIFICAR SI NECESITA BALANCE
    // ============================================

    const difference = Math.abs(redCountRoom - blueCountRoom);

    // Si la diferencia es 1 o menos, los equipos ya están balanceados
    if (difference <= 1) {
        return;
    }

    // ============================================
    // 5. MOVER JUGADOR AL EQUIPO MÁS PEQUEÑO
    // ============================================

    let playerToMove = null;
    let targetTeam = null;

    if (redCountRoom > blueCountRoom) {
        // Mover el último jugador de RED a BLUE
        playerToMove = redPlayers[redPlayers.length - 1];
        targetTeam = 2; // BLUE
    } else {
        // Mover el último jugador de BLUE a RED
        playerToMove = bluePlayers[bluePlayers.length - 1];
        targetTeam = 1; // RED
    }

    // ============================================
    // 6. EJECUTAR EL MOVIMIENTO
    // ============================================

    if (playerToMove) {
        room.setPlayerTeam(playerToMove.id, targetTeam);

        // Log opcional para debugging
        const sourceTeam = targetTeam === 1 ? "BLUE" : "RED";
        const destTeam = targetTeam === 1 ? "RED" : "BLUE";

        console.log(
            `[BALANCE] Jugador "${playerToMove.name}" movido de ${sourceTeam} a ${destTeam}. ` +
            `Nueva distribución: RED=${redCountRoom - (targetTeam === 1 ? 1 : 0)}, BLUE=${blueCountRoom - (targetTeam === 2 ? 1 : 0)}`
        );

        // Mensaje opcional en el chat
        room.sendAnnouncement(`⚖️ Equipos balanceados automáticamente (${currentMode}) Jugador "${playerToMove.name}" movido de ${sourceTeam} a ${destTeam}.`, null, colors.botGold, "bold", 2);
    }
}

