function resetMvpStats() {
    mvpStats = {};
    room.getPlayerList().forEach(player => {
        initMvpStats(player);
    });
}

function printMvpCandidates() {
    const mvpEmojis = ["１", "２", "３"];
    const dtIds = [dts.red, dts.blue].filter(Boolean); // Solo los que no son null

    const candidates = Object.entries(mvpStats)
        .filter(([id, stats]) => {
            // Excluir si el id es igual al DT de red o blue
            return stats.mvpScore > 0 && !dtIds.includes(Number(id));
        })
        .sort((a, b) => b[1].mvpScore - a[1].mvpScore)
        .slice(0, 3);

    if (candidates.length > 0) {
        let msg = "━━━━━━━━━━━━━━━━━━━━━━\n";
        msg += "🏆 𝘾𝘼𝙉𝘿𝙄𝘿𝘼𝙏𝙊𝙎 𝙈𝙑𝙋 🏆\n";
        msg += "━━━━━━━━━━━━━━━━━━━━━━\n";
        candidates.forEach(([id, stats], idx) => {
            const player = room.getPlayer(Number(id));
            if (player) {
                msg += `${mvpEmojis[idx] || "◈"} ${player.name}  —  ❪ ${stats.mvpScore.toFixed(2)} ❫  pts\n`;
            }
        });
        msg += "━━━━━━━━━━━━━━━━━━━━━━";
        room.sendAnnouncement(msg, null, colors.botGold, "bold", 2);
    } else {
        room.sendAnnouncement("❌ No hay candidatos al MVP aún.", null, colors.mvp, "bold", 2);
    }
}

function printMvpWinner() {
    const dtIds = [dts.red, dts.blue].filter(Boolean);

    const mvpWinner = Object.entries(mvpStats)
        .filter(([id, stats]) => {
            return stats.mvpScore > 0 && !dtIds.includes(Number(id));
        })
        .sort((a, b) => b[1].mvpScore - a[1].mvpScore)
        .slice(0, 1); // Solo el primero

    if (mvpWinner.length > 0) {
        const [id, stats] = mvpWinner[0];
        const player = room.getPlayer(Number(id));

        if (player) {
            const teamEmoji = player.team === 1 ? "🔴" : "🔵";
            const fancyName = player.name
                .toUpperCase()
                .replace(/A/g, "𝘼").replace(/B/g, "𝘽").replace(/C/g, "𝘾")
                .replace(/D/g, "𝘿").replace(/E/g, "𝙀").replace(/F/g, "𝙁")
                .replace(/G/g, "𝙂").replace(/H/g, "𝙃").replace(/I/g, "𝙄")
                .replace(/J/g, "𝙅").replace(/K/g, "𝙆").replace(/L/g, "𝙇")
                .replace(/M/g, "𝙈").replace(/N/g, "𝙉").replace(/O/g, "𝙊")
                .replace(/P/g, "𝙋").replace(/Q/g, "𝙌").replace(/R/g, "𝙍")
                .replace(/S/g, "𝙎").replace(/T/g, "𝙏").replace(/U/g, "𝙐")
                .replace(/V/g, "𝙑").replace(/W/g, "𝙒").replace(/X/g, "𝙓")
                .replace(/Y/g, "𝙔").replace(/Z/g, "𝙕");

            const msg =
                "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n" +
                `🏆 𝖬𝖵𝖯: ${teamEmoji} ${fancyName} — ${stats.mvpScore.toFixed(2)} 𝖯𝖳𝖲\n` +
                "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━";

            room.sendAnnouncement(msg, null, colors.mvp, "bold", 2);
        }
    } else {
        room.sendAnnouncement("❌ No hay MVP aún.", null, colors.mvp, "bold", 2);
    }
}

function printMvpGKCandidates() {
    const mvpEmojis = ["1️⃣", "2️⃣", "3️⃣"];
    // Solo jugadores con posición GK y mvpScore > 0
    const candidates = Object.entries(mvpStats)
        .filter(([id, stats]) => {
            const player = room.getPlayer(Number(id));
            // Verifica que el jugador exista y tenga posición GK
            return player && getPlayerPosition(player) === "GK" && stats.mvpScore > 0;
        })
        .sort((a, b) => b[1].mvpScore - a[1].mvpScore)
        .slice(0, 3);

    if (candidates.length > 0) {
        let msg = "━━━━━━━━━━━━━━━━━━━━━━\n";
        msg += "🏆 𝙏𝙊𝙋 𝙂𝙆 𝙈𝙑𝙋 🏆\n";
        msg += "━━━━━━━━━━━━━━━━━━━━━━\n";
        candidates.forEach(([id, stats], idx) => {
            const player = room.getPlayer(Number(id));
            if (player) {
                msg += `${mvpEmojis[idx] || "⭐"} ${player.name}  —  ${stats.mvpScore.toFixed(2)} pts\n`;
            }
        });
        msg += "━━━━━━━━━━━━━━━━━━━━━━";
        room.sendAnnouncement(msg, null, colors.botGold, "bold", 2);
    } else {
        room.sendAnnouncement("❌ No hay candidatos al MVP GK aún.", null, colors.mvp, "bold", 2);
    }
}
function showTop3MVPs() {
    const top3Players = Object.entries(mvpStats)
        .filter(([id, stats]) => stats.mvpScore > 0) // Filtrar jugadores con puntaje > 0
        .sort(([, a], [, b]) => b.mvpScore - a.mvpScore) // Ordenar por puntaje descendente
        .slice(0, 3); // Tomar los 3 primeros

    if (top3Players.length === 0) {
        room.sendAnnouncement("No hay suficientes datos para determinar candidatos al MVP.", null, colors.bot, "bold", 2);
        return;
    }

    let message = "🏆 𝘾𝘼𝙉𝘿𝙄𝘿𝘼𝙏𝙊𝙎 𝘼𝙇 𝙈𝙑𝙋 🏆\n";
    top3Players.forEach(([id, stats], index) => {
        const player = room.getPlayer(+id);
        if (player) {
            message += `${index + 1}. ${player.name} - ${stats.mvpScore.toFixed(2)} puntos\n`;
        }
    });

    room.sendAnnouncement(message, null, colors.botGold, "bold", 2);
}

function getTopMVPCandidates() {
    // Crear un array con las estadísticas de los jugadores
    const players = room.getPlayerList().filter(player => mvpStats[player.id]);
    const candidates = players.map(player => ({
        id: player.id,
        name: player.name,
        mvpScore: calculateMVPScore(player.id) // Asumiendo que tienes una función para calcular el puntaje MVP
    }));

    // Ordenar los jugadores por su puntaje MVP en orden descendente
    candidates.sort((a, b) => b.mvpScore - a.mvpScore);

    // Retornar los 3 mejores candidatos
    return candidates.slice(0, 3);
}

function calculateMVPScore(playerId) {
    const stats = mvpStats[playerId];
    if (!stats) return 0;

    // Ejemplo de cálculo de puntaje MVP basado en estadísticas
    return (
        stats.goals * 4 +
        stats.assists * 3 +
        stats.saves * 2 +
        stats.interceptions * 1.5 +
        stats.clearances * 1 +
        stats.defensiveTouches * 0.5 +
        stats.distanceTraveled * 0.1 -
        stats.ownGoals * 2 -
        stats.goalsConceded * 1
    );
}


