    // Resetear los MVPs antes de iniciar la votación
    mvps.forEach(mvpId => {
        const mvpPlayer = room.getPlayer(mvpId);
        if (mvpPlayer) {
            room.setPlayerAvatar(mvpPlayer.id, null); // Restaurar el avatar a null
        }
    });
    mvps.clear(); // Limpiar el conjunto de MVPs

    votacionMVPActiva = true;
    votosMVP.clear();
    votosEmitidosMVP.clear();
