function resetMVP() {
    mvps.forEach(playerId => {
        const player = room.getPlayer(playerId);
        if (player) {
            removeMVP(player);
        }
    });
    mvps.clear();
}

function calculateMVP() {
    let maxScore = -Infinity;
    let mvpPlayer = null;

    for (let playerId in mvpStats) {
        const stats = mvpStats[playerId];
        const totalScore = (stats.goals * 2.5) + (stats.assists * 2) + (stats.saves * 3) +
            (stats.interceptions * 1.5) + (stats.clearances * 1) +
            (stats.defensiveTouches * 0.2) + (stats.touches * 0.05) +
            (stats.distanceTraveled * 0.5);

        if (totalScore > maxScore) {
            maxScore = totalScore;
            mvpPlayer = room.getPlayer(parseInt(playerId));
        }
    }

    if (mvpPlayer) {
        room.sendAnnouncement(`🏆 MVP: ${mvpPlayer.name} with a score of ${maxScore.toFixed(2)}!`, null, 0xFFD700, "bold", 2);
    }
}

function handleAssignMVPCommand(player, message) {
    // Verificar si el jugador que ejecuta el comando tiene permisos
    const isAdmin = admins.has(player.id) || player.id === creator || hosters.has(player.id);
    if (!isAdmin) {
        room.sendAnnouncement("❌ No tienes permiso para usar este comando.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Dividir el mensaje para obtener el ID del jugador objetivo
    const args = message.split(" ");
    if (args.length !== 2) {
        room.sendAnnouncement("❌ Uso incorrecto del comando. Usa: !assignmvp [ID]", player.id, colors.bot, "bold", 2);
        return false;
    }

    const targetId = parseInt(args[1], 10);
    const targetPlayer = room.getPlayer(targetId);

    // Verificar si el jugador objetivo existe
    if (!targetPlayer) {
        room.sendAnnouncement("❌ No se encontró al jugador con el ID especificado.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Asignar el rol de MVP al jugador objetivo
    assignMVP(targetPlayer);

    // Anunciar que el jugador ha sido asignado como MVP
    room.sendAnnouncement(`🏆 ${targetPlayer.name} ha sido asignado como MVP por ${player.name}.`, null, colors.mvp, "bold", 2);

    return false;
}

