function handleToggleMetergkCommand(player, message) {
    // Verificar si el jugador tiene permisos (creador o hoster)
    if (!hosters.has(player.id) && player.id !== creator) {
        room.sendAnnouncement("No tienes permisos para usar este comando.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Dividir el mensaje en partes
    const args = message.split(" ");
    if (args.length !== 2 || (args[1] !== "1" && args[1] !== "0")) {
        room.sendAnnouncement("Uso incorrecto. Usa !togglemetergk 1 para habilitar o !togglemetergk 0 para deshabilitar.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Actualizar el estado de metergkEnabled
    metergkEnabled = args[1] === "1";
    room.sendAnnouncement(` \n 🔓 ¡𝗦𝗘 𝗛𝗔 ${metergkEnabled ? "𝗛𝗔𝗕𝗜𝗟𝗜𝗧𝗔𝗗𝗢" : "𝗗𝗘𝗦𝗛𝗔𝗕𝗜𝗟𝗜𝗧𝗔𝗗𝗢"} 𝗘𝗟 𝗨𝗦𝗢 𝗗𝗘 !𝗠𝗘𝗧𝗘𝗥𝗚𝗞 𝗣𝗔𝗥𝗔 𝗟𝗢𝗦 𝗗𝗧𝘀! 🧤⚽ . \n `, null, colors.bot, "bold", 2);
    return false;
}

function handleMeterGKCommand(player, message) {
    // Verificar si el comando está habilitado
    if (!metergkEnabled) {
        room.sendAnnouncement("El comando !metergk está deshabilitado.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Verificar si el jugador es DT
    if (player.id !== dts.red && player.id !== dts.blue) {
        room.sendAnnouncement("Solo los DTs pueden usar este comando.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Dividir el mensaje en partes
    const args = message.split(" ");
    if (args.length !== 3 || (args[1] !== "red" && args[1] !== "blue")) {
        room.sendAnnouncement("Uso incorrecto. Usa !metergk [red/blue] [ID].", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Obtener el equipo y el ID del jugador
    const team = args[1];
    const playerId = parseInt(args[2], 10);

    if (isNaN(playerId)) {
        room.sendAnnouncement("ID de jugador inválido.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const targetPlayer = room.getPlayer(playerId);
    if (!targetPlayer) {
        room.sendAnnouncement("Jugador no encontrado.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // Verificar que el jugador esté en el equipo correcto
    if (team === "red" && targetPlayer.team !== 1) {
        room.sendAnnouncement("El jugador no está en el equipo rojo.", player.id, colors.bot, "bold", 2);
        return false;
    }

    if (team === "blue" && targetPlayer.team !== 2) {
        room.sendAnnouncement("El jugador no está en el equipo azul.", player.id, colors.bot, "bold", 2);
        return false;
    }

    // --- USAR COORDENADAS DINÁMICAS DEL MAPA ---
    const cfg = getMapConfig();
    const goalPosition = team === "red" ? cfg.gkRed : cfg.gkBlue;

    // Teletransportar al jugador a la posición del arco
    room.setPlayerDiscProperties(targetPlayer.id, { x: goalPosition.x, y: goalPosition.y });
    room.sendAnnouncement(`${targetPlayer.name} ha sido teletransportado al arco del equipo ${team === "red" ? "Rojo" : "Azul"}.`, null, colors.bot, "bold", 2);

    return false;
}

function handleMeterCommand(player, message) {
    const args = message.split(" ");
    if (args.length !== 2) {
        room.sendAnnouncement("Uso incorrecto del comando. Usa !meter id.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const playerId = parseInt(args[1], 10);
    if (isNaN(playerId)) {
        room.sendAnnouncement("ID inválido.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const targetPlayer = room.getPlayer(playerId);
    if (!targetPlayer) {
        room.sendAnnouncement("Jugador no encontrado.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const team = player.team;
    if (team !== 1 && team !== 2) {
        room.sendAnnouncement("Debes estar en un equipo para usar este comando.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const targetTeam = team === 1 ? 2 : 1;
    room.setPlayerTeam(targetPlayer.id, targetTeam);

    room.sendAnnouncement(`${targetPlayer.name} ha sido metido al equipo ${targetTeam === 1 ? "Rojo" : "Azul"}.`, null, colors.bot, "bold", 2);
    return false;
}

function handleSacarCommand(player, message) {
    const args = message.split(" ");
    if (args.length !== 2) {
        room.sendAnnouncement("Uso incorrecto del comando. Usa !sacar id.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const playerId = parseInt(args[1], 10);
    if (isNaN(playerId)) {
        room.sendAnnouncement("ID inválido.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const targetPlayer = room.getPlayer(playerId);
    if (!targetPlayer) {
        room.sendAnnouncement("Jugador no encontrado.", player.id, colors.bot, "bold", 2);
        return false;
    }

    const originalTeam = targetPlayer.team;
    if (originalTeam !== 1 && originalTeam !== 2) {
        room.sendAnnouncement("El jugador ya está en espectadores.", player.id, colors.bot, "bold", 2);
        return false;
    }

    room.setPlayerTeam(targetPlayer.id, 0); // Mover a espectadores

    setTimeout(() => {
        room.setPlayerTeam(targetPlayer.id, originalTeam); // Devolver al equipo original
        room.sendAnnouncement(`${targetPlayer.name} ha sido devuelto al equipo ${originalTeam === 1 ? "Rojo" : "Azul"}.`, null, colors.bot, "bold", 2);
    }, 5000); // Esperar 5 segundos antes de devolver al equipo original

    room.sendAnnouncement(`${targetPlayer.name} ha sido movido a espectadores temporalmente.`, null, colors.bot, "bold", 2);
    return false;
}

function generateRandomCode(len = 6) {
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    let out = "";
    for (let i = 0; i < len; i++) out += chars.charAt(Math.floor(Math.random() * chars.length));
    return out;
}



