room.onRoomLink = function (roomLink) {
    lastRoomLink = roomLink;
    sendRoomLinkToDiscord(); // ✅ Se ejecuta automáticamente
};

function sendRoomLinkToDiscord() {
    if (!lastRoomLink) {
        room.sendAnnouncement("El link del server aún no está disponible.", null, 0xFF0000, "bold");
        return;
    }

    const data = {
        content: `🔗 **Link del server:** ${lastRoomLink}`
    };

    fetch(webhookRoomURL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data)
    })
        .then(res => {
            if (res.ok) {
                room.sendAnnouncement("✅ Link enviado a Discord correctamente.", null, 0x1EFF82, "bold");
            } else {
                room.sendAnnouncement("❌ Error al enviar el link a Discord.", null, 0xFF0000, "bold");
            }
        })
        .catch(err => {
            room.sendAnnouncement("⚠️ Error de conexión al enviar el link a Discord.", null, 0xFF0000, "bold");
        });
}

