function checkPowerShotCharge() {
    const now = Date.now();
    const players = room.getPlayerList();

    if (!players || players.length === 0) return;

    for (const player of players) {
        if (!player || player.id === 0) continue;

        const stats = mvpStats[player.id];
        const ps = powerShotData[player.id];
        if (!stats || !ps) continue;

        // Si ya tiene una carga o está en cooldown, saltar
        if (ps.charges >= 1 || ps.cooldown) continue;

        // Usa la distancia recorrida real
        const dist = stats.distanceTraveled || 0;

        // Si recorrió suficiente distancia desde la última carga
        if (dist - ps.lastDistance >= PowerShotDistance) {
            // Cooldown global para evitar spam de mensajes
            if (!ps.lastUsed || now - ps.lastUsed >= PowerShotCooldown) {
                // Mensaje solo si no se ha anunciado en los últimos 30 segundos
                if (!lastPowerShotAnnounce.has(player.id) || now - lastPowerShotAnnounce.get(player.id) > 30000) {
                    if (powershotmode) {
                        room.sendAnnouncement(`════════════════════════════
⚡ 𝗣𝗢𝗪𝗘𝗥𝗦𝗛𝗢𝗧 𝗖𝗔𝗥𝗚𝗔𝗗𝗢 ⚡
════════════════════════════
${player.name} puede activarlo con !ps.`, player.id, 0xfe024d, "bold", 2);
                    }
                    lastPowerShotAnnounce.set(player.id, now);
                }
                ps.charges = 1;
                ps.lastDistance = dist;
                ps.lastUsed = now;
            }
        }
    }
    // --- COMBA CHARGING LOOP (identical to PowerShot) ---
    for (const player of players) {
        if (!player || player.id === 0) continue;

        const stats = mvpStats[player.id];
        const cb = combaData[player.id];
        if (!stats || !cb) continue;

        if (cb.charges >= 1 || cb.cooldown) continue;

        const dist = stats.distanceTraveled || 0;

        if (dist - cb.lastDistance >= combaShotDistance) {
            if (!cb.lastUsed || now - cb.lastUsed >= combaShotCooldown) {
                if (!lastCombaAnnounce.has(player.id) || now - lastCombaAnnounce.get(player.id) > 30000) {
                    if (combaMode) {
                        room.sendAnnouncement(`════════════════════════════
🟢 𝗖𝗢𝗠𝗕𝗔 𝗖𝗔𝗥𝗚𝗔𝗗𝗢 🟢
════════════════════════════
${player.name} puede activarlo con !cmb.`, player.id, 0x00FF00, "bold", 2);
                    }
                    lastCombaAnnounce.set(player.id, now);
                }
                cb.charges = 1;
                cb.lastDistance = dist;
                cb.lastUsed = now;
            }
        }
    }
}

