function controlarVerificacion(matchON) {
    if (matchON) {
        // Evita crear múltiples intervalos
        if (intervalVerificarAvatar === null) {
            intervalVerificarAvatar = setInterval(verificarYRestaurarAvataresCapitanes, 15000);
            intervalRestaurarAvataresDT = setInterval(verificarYRestaurarAvataresDT, 15000);
            intervalRestaurarAvatarMVP = setInterval(verificarYRestaurarAvataresMVP, 15000);
        }
    } else {
        // Detiene el intervalo
        if (intervalVerificarAvatar !== null) {
            clearInterval(intervalVerificarAvatar);
            clearInterval(intervalRestaurarAvataresDT);
            clearInterval(intervalRestaurarAvatarMVP);
            intervalVerificarAvatar = null;
        }
    }
}

