function sendRTD(recordingBuffer) {
    const now = new Date();
    const fileName = `HaxBallReplay_${now.getFullYear()}-${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}_${now.getHours().toString().padStart(2, '0')}-${now.getMinutes().toString().padStart(2, '0')}-${now.getSeconds().toString().padStart(2, '0')}.hbr2`;

    let formData = new FormData();
    let blob = new Blob([recordingBuffer], { type: "application/octet-stream" });
    formData.append("file", blob, fileName);

    // Añadir un mensaje adicional
    const dateTimeString = `📅 ${now.getDate().toString().padStart(2, '0')}/${(now.getMonth() + 1).toString().padStart(2, '0')}/${now.getFullYear()} - 🕒 ${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    const globalRedScore = matchStats.ida.redScore + matchStats.vuelta.redScore;
    const globalBlueScore = matchStats.ida.blueScore + matchStats.vuelta.blueScore;
    // Obtener el top 3 de MVPs por mvpScore
    const topMVPs = Object.entries(mvpStats)
        .filter(([id, stats]) => stats.mvpScore > 0)
        .sort((a, b) => b[1].mvpScore - a[1].mvpScore)
        .slice(0, 3)
        .map(([id, stats], idx) => {
            // Buscar el nombre del jugador por id
            const player = room.getPlayer(parseInt(id));
            const name = player ? player.name : `ID:${id}`;
            // Puedes mostrar el puntaje si quieres
            return `${idx === 0 ? "<:IEstrellaKL:1394794902155690004>" : idx === 1 ? "<:IEstrellaMC:1394799717866672139>" : "<:IEstrellaSC:1394799256270930142>"} ${name} ( ${stats.mvpScore.toFixed(2)} )`;
        });

    const mvpListText = topMVPs.length > 0
        ? `𝗝𝗨𝗚𝗔𝗗𝗢𝗥𝗘𝗦 𝗠𝗩𝗣:\n${topMVPs.join('\n')}\n━━━━━━━━━━━━━━━━━━━━━━`
        : '';

    formData.append("content",
        `━━━━━━━━━━━━━━━━━━━━━━
#   𝗞𝗡𝗜𝗚𝗛𝗧𝗦 <:Cknights:1394217111366406207>
## ⛨ 𝗧𝗢𝗗𝗢𝗦 𝗝𝗨𝗘𝗚𝗔𝗡 ⛨ 
 ${dateTimeString} 
━━━━━━━━━━━━━━━━━━━━━━
 𝙈𝘼𝙍𝘾𝘼𝘿𝙊𝙍 𝙁𝙄𝙉𝘼𝙇:
🔴（ ${globalRedScore} - ${globalBlueScore} ）🔵
━━━━━━━━━━━━━━━━━━━━━━
${mvpListText}`
    );
    fetch(webhookTJM, {
        method: "POST",
        body: formData
    })
        .then(response => {
            if (response.ok) {
                console.log("✅📤 ¡𝗚𝗥𝗔𝗕𝗔𝗖𝗜𝗢𝗡 𝗘𝗡𝗩𝗜𝗔𝗗𝗔 𝗖𝗢𝗡 𝗘𝗫𝗜𝗧𝗢 𝗔 𝗗𝗜𝗦𝗖𝗢𝗥𝗗! 💾🔥");
            } else {
                console.error("Error en la respuesta:", response.status);
                room.sendAnnouncement("❌ Error al enviar la grabación a Discord.", null, 0xff0000, "bold", 2);
                sendLogToDiscord("❌ Error al enviar la grabación a Discord.");
            }
        })
        .catch(error => {
            room.sendAnnouncement("❌ Fallo en la conexión con Discord.", null, 0xff0000, "bold", 2);
            console.error("Error enviando la grabación:", error);
        });
}

// Cargar estadísticas desde localStorage
function loadStatsFromLocalStorage() {
    try {
        const stats = JSON.parse(localStorage.getItem('playerStatsAuthMap')) || {};
        for (const [auth, data] of Object.entries(stats)) {
            playerStatsAuthMap.set(auth, data);
        }
        return stats;
    } catch (error) {
        console.error('Error loading stats from localStorage:', error);
        return {};
    }
}


let playerStats = loadStatsFromLocalStorage();

function saveStatsToLocalStorage() {
    try {
        // ✅ IMPROVED: Filter non-serializable values before converting
        const statsObj = {};
        for (const [key, value] of playerStatsAuthMap) {
            try {
                // Only include serializable properties
                statsObj[key] = {
                    name: value.name || "Unknown",
                    goals: Number(value.goals) || 0,
                    assists: Number(value.assists) || 0,
                    gamesPlayed: Number(value.gamesPlayed) || 0,
                    gamesDrawn: Number(value.gamesDrawn) || 0,
                    gamesWon: Number(value.gamesWon) || 0,
                    gamesLost: Number(value.gamesLost) || 0,
                    ownGoals: Number(value.ownGoals) || 0,
                    completedPasses: Number(value.completedPasses) || 0,
                    cleanSheets: Number(value.cleanSheets) || 0,
                    mvps: Number(value.mvps) || 0
                };
            } catch (itemError) {
                console.warn(`Skipping non-serializable stat for ${key}:`, itemError);
            }
        }
        localStorage.setItem('playerStatsAuthMap', JSON.stringify(statsObj));
    } catch (error) {
        console.error('Error saving stats to localStorage:', error);
    }
}

