function showGlobalRanking(player, type) {
    // Mapeo de criterios y textos
    const criteria = {
        gol: { key: "goals", label: "G", emoji: "⚽", title: "Goles" },
        assist: { key: "assists", label: "A", emoji: "🎯", title: "Asistencias" },
        mvp: { key: "mvps", label: "MVP", emoji: "🏆", title: "MVP" },
        wr: { key: "wr", label: "WR", emoji: "📈", title: "Winrate" }
    };
    const c = criteria[type];
    if (!c) return;

    // Recolectar todos los auths históricos
    const allAuths = Array.from(playerStatsAuthMap.keys());
    // Construir array de objetos {auth, nombre, goals, assists, mvps, gamesWon, gamesLost}
    const statsArr = allAuths.map(auth => {
        const stats = loadPlayerStats(auth);
        const totalGames = stats.gamesWon + stats.gamesLost;
        const wr = totalGames > 0 ? ((stats.gamesWon / totalGames) * 100) : 0;
        return {
            auth,
            name: (stats.name || "???").toUpperCase(),
            goals: stats.goals || 0,
            assists: stats.assists || 0,
            mvps: stats.mvps || 0,
            gamesWon: stats.gamesWon || 0,
            gamesLost: stats.gamesLost || 0,
            wr: wr
        };
    });

    // Ordenar según el tipo
    statsArr.sort((a, b) => {
        if (type === "wr") {
            // Winrate: mínimo 10 partidos para aparecer arriba
            const aGames = a.gamesWon + a.gamesLost, bGames = b.gamesWon + b.gamesLost;
            if (aGames < 10 && bGames >= 10) return 1;
            if (bGames < 10 && aGames >= 10) return -1;
            if (b.wr !== a.wr) return b.wr - a.wr;
            return (b.gamesWon + b.gamesLost) - (a.gamesWon + a.gamesLost); // desempate: más partidos
        }
        // Otros: por cantidad, desempate por nombre
        if (b[c.key] !== a[c.key]) return b[c.key] - a[c.key];
        return a.name.localeCompare(b.name);
    });

    // Buscar posición del jugador
    const playerAuth = getPlayerAuth(player);
    const playerIdx = statsArr.findIndex(obj => obj.auth === playerAuth);

    // Mensaje TOP 3
    let msg = "";
    for (let i = 0; i < 3 && i < statsArr.length; i++) {
        const medal = ["🥇", "🥈", "🥉"][i];
        const val = type === "wr"
            ? (statsArr[i].wr.toFixed(1) + "%")
            : statsArr[i][c.key];
        msg += `${medal} ${i + 1}. ${statsArr[i].name} - ${val}\n`;
    }
    msg += "\n";

    // Mensaje de posición personal
    if (playerIdx !== -1) {
        const p = statsArr[playerIdx];
        msg += `👤 ${p.name} - TU POSICIÓN: #${playerIdx + 1}\n`;
        msg += `⚽ G: ${p.goals} 🎯 A: ${p.assists} 🏆 MVP: ${p.mvps} 📈 WR: ${p.wr.toFixed(1)}%`;
    } else {
        msg += "👤 No tienes estadísticas registradas.";
    }

    room.sendAnnouncement(msg, player.id, 0xFFD700, "small", 2);
}

function sendStatsToDiscord() {
    const playerList = room.getPlayerList();
    const statsArray = Array.from(playerStatsAuthMap.entries())
        .filter(([auth, stats]) => stats.gamesPlayed > 0) // Filtrar jugadores con al menos un partido jugado
        .map(([auth, stats]) => {
            const player = playerList.find(p => p.auth === auth);
            const playerName = player ? player.name : `Auth: ${auth}`;
            return {
                playerName,
                goals: stats.goals,
                assists: stats.assists,
                gamesPlayed: stats.gamesPlayed,
                gamesWon: stats.gamesWon,
                gamesLost: stats.gamesLost
            };
        });

    const statsMessage = statsArray.map(stat => {
        return `${stat.playerName}, Goals: ${stat.goals}, Assists: ${stat.assists}, Games Played: ${stat.gamesPlayed}, Games Won: ${stat.gamesWon}, Games Lost: ${stat.gamesLost}`;
    }).join('\n');

    fetch(webhookURL, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ content: statsMessage })
    }).then(response => {
        if (response.ok) {
            console.log('Stats sent to Discord successfully');
        } else {
            console.error('Error sending stats to Discord:', response.statusText);
        }
    }).catch(error => {
        console.error('Error sending stats to Discord:', error);
    });
}

