function handleRankTopCommand() {
    const topPlayers = Array.from(playerStatsAuthMap.entries())
        .filter(([auth, stats]) => stats.gamesPlayed >= 50) // Filtrar jugadores con al menos 50 partidos jugados
        .map(([auth, stats]) => ({
            auth,
            winPercentage: stats.gamesPlayed > 0 ? (stats.gamesWon / stats.gamesPlayed) * 100 : 0
        }))
        .sort((a, b) => b.winPercentage - a.winPercentage) // Ordenar por porcentaje de victorias descendente
        .slice(0, 5); // Tomar los 5 primeros

    let message = "📊 𝙏𝙊𝙋 5 𝙅𝙐𝙂𝘼𝘿𝙊𝙍𝙀𝙎 (𝙋𝙊𝙍𝘾𝙀𝙉𝙏𝘼𝙅𝙀 𝘿𝙀 𝙂𝘼𝙉𝘼𝘿𝙊𝙎) 📊\n";
    topPlayers.forEach((player, index) => {
        const stats = playerStatsAuthMap.get(player.auth);
        const playerObj = room.getPlayerList().find(p => p.auth === player.auth);
        const playerName = playerObj ? playerObj.name : "Jugador desconocido";
        message += `${index + 1}. ${playerName} - ${player.winPercentage.toFixed(2)}% (${stats.gamesPlayed} 𝙋𝘼𝙍𝙏𝙄𝘿𝙊𝙎)\n`;
    });

    room.sendAnnouncement(message, null, colors.botGold, "bold", 2);
}

function canUseRankCommand(player, command) {
    const now = Date.now();
    if (!rankCooldowns.has(player.id)) {
        rankCooldowns.set(player.id, {});
    }

    const playerCooldowns = rankCooldowns.get(player.id);
    if (!playerCooldowns[command] || now - playerCooldowns[command] > RANK_COOLDOWN_TIME) {
        playerCooldowns[command] = now;
        return true;
    }

    const remainingTime = Math.ceil((RANK_COOLDOWN_TIME - (now - playerCooldowns[command])) / 1000);
    room.sendAnnouncement(`Debes esperar ${remainingTime} segundos antes de usar el comando ${command} nuevamente.`, player.id, colors.bot, "bold", 2);
    return false;
}

function getPlayerRank(auth, arr, key) {
    let idx = arr.findIndex(e => e.auth === auth);
    return idx >= 0 ? idx + 1 : null;
}

