function showRanking(statKey, displayName, player) {
    let rankings = getRankings();
    console.log(rankings); // <-- ¿Ves lastName en los objetos?
    // Convertir rankings a array
    let arr = Object.values(rankings).filter(x => x.lastName && x.lastName.length > 0);

    // Si no hay datos, avisar
    if (arr.length === 0) {
        room.sendAnnouncement("No hay datos suficientes para mostrar el ranking.", player?.id || null, 0xFF0000, "bold", 2);
        return;
    }

    // Ordenar por statKey descendente
    arr.sort((a, b) => (b[statKey] || 0) - (a[statKey] || 0));

    // Top 5
    let top = arr.slice(0, 5);

    let msg = `🏆 Top 5 de ${displayName}:\n`;
    for (let i = 0; i < top.length; i++) {
        msg += `${i + 1}. ${top[i].lastName} - ${top[i][statKey] || 0}\n`;
    }

    // Mostrar posición personal si tiene auth
    let personalMsg = "";
    if (player && player.auth) {
        let myIndex = arr.findIndex(p => p.auth === player.auth);
        if (myIndex !== -1) {
            let myStats = arr[myIndex];
            personalMsg = `\nTu posición: #${myIndex + 1} - ${myStats.lastName} - ${myStats[statKey] || 0}`;
        }
    }

    room.sendAnnouncement(msg.trim() + personalMsg, player?.id || null, 0x00FF00, "bold", 2);
}

