function sendWelcomeToNarrator(player) {
    if (narrador === 0) return;
    if (!player || !player.name) return;

    // Cooldown por jugador
    const now = Date.now();
    const lastTime = welcomeNarratorCooldown.get(player.id) || 0;
    if (now - lastTime < WELCOME_NARRATOR_COOLDOWN_MS) return;
    welcomeNarratorCooldown.set(player.id, now);

    // Usa {name} como placeholder en la frase
    const simpleName = simplificarNombre(player.name);
    const phrase = welcomeNarratorPhrases[Math.floor(Math.random() * welcomeNarratorPhrases.length)]
        .replace(/{name}/g, simpleName);

    fetch("", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ texto: phrase })
    }).catch(() => { });
}

