function sendFailedPassToNarrator(passInitiator, receiver) {
    if (narrador === 0) return;
    //sendLogBallkickToDiscord(`${passInitiator.name} sendFailedPassToNarrator. narrador: ${narrador}`);
    //if (!player || !player.name) return;
    const now = Date.now();
    if (
        failedPassNarratorCooldown.has(passInitiator.id) &&
        now - failedPassNarratorCooldown.get(passInitiator.id) < FAILED_PASS_NARRATOR_COOLDOWN_MS
    ) {
        return; // En cooldown, no narrar
    }
    failedPassNarratorCooldown.set(passInitiator.id, now);

    const simpleName = simplificarNombre(passInitiator.name);
    const phrase = failedPassNarratorPhrases[Math.floor(Math.random() * failedPassNarratorPhrases.length)]
        .replace(/{name}/g, simpleName);

    fetch("", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ texto: phrase })
    }).catch(() => { });
}

function sendShotInBoxToNarrator(player) {
    if (narrador === 0) return;
    //sendLogBallkickToDiscord(`${player.name} sendShotInBoxToNarrator. narrador: ${narrador}`);
    //if (!player || !player.name) return;
    const now = Date.now();
    if (lastShotInBoxTime[player.id] && now - lastShotInBoxTime[player.id] < SHOT_IN_BOX_COOLDOWN) {
        return; // Aún en cooldown, no enviar
    }
    lastShotInBoxTime[player.id] = now;

    const simpleName = simplificarNombre(player.name);
    const phrase = shotInBoxPhrases[Math.floor(Math.random() * shotInBoxPhrases.length)]
        .replace(/{name}/g, simpleName);

    fetch("", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ texto: phrase })
    }).catch(() => { });
}

