room.onGamePause = function (byPlayer) {
    matchON = false; // ✅ Pausa: desactiva AFK}
    if (AF4v4mode) {
        af4IsPaused = true;
        console.log("[AF4v4] onGamePause: af4IsPaused = true");
    }
    if (afkSystemEnabled) {
        let players = room.getPlayerList();
        players.forEach(p => {
            stopAfkTimer(p.id); // Limpiar timers anteriores
            startAfkTimer(p);      // Reiniciar timer
        });
    }
    if (byPlayer) {
        room.sendAnnouncement(`════════════════════════ \n   ⏸️ 𝗝𝗨𝗘𝗚𝗢 𝗣𝗔𝗨𝗦𝗔𝗗𝗢 ⏸️ ${byPlayer.name} \n════════════════════════`, null, colors.botGold, "bold", 2);
        console.log(`El jugador ${byPlayer.name} (ID: ${byPlayer.id}) ha pausado el juego.`);
        sendLogPausasToDiscord(`El jugador ${byPlayer.name} (ID: ${byPlayer.id}) ha pausado el juego.`);
    } else {
        console.log("El juego ha sido pausado automáticamente o por el sistema.");
    }
};

room.onGameUnpause = function (byPlayer) {
    matchON = true; // ✅ Reanuda: activa AFK
    if (AF4v4mode) {
        af4IsPaused = false;
        console.log("[AF4v4] onGameUnpause: af4IsPaused = false");
    }
    if (afkSystemEnabled) {
        let players = room.getPlayerList();
        players.forEach(p => {
            stopAfkTimer(p.id); // Limpiar timers anteriores
            startAfkTimer(p);      // Reiniciar timer
        });
    }
    if (byPlayer) {
        room.sendAnnouncement(`════════════════════════ \n   ⏸️ 𝗝𝗨𝗘𝗚𝗢 𝗗𝗘𝗦𝗣𝗔𝗨𝗦𝗔𝗗𝗢 ⏸️ ${byPlayer.name} \n════════════════════════`, null, colors.botGold, "bold", 2);
        console.log(`El jugador ${byPlayer.name} (ID: ${byPlayer.id}) ha despausado el juego.`);
        sendLogPausasToDiscord(`El jugador ${byPlayer.name} (ID: ${byPlayer.id}) ha despausado el juego.`);
    } else {
        console.log("El juego ha sido despausado automáticamente o por el sistema.");
    }
};

